import"./chunk-ACKELEN3.js";var a=[{id:1,capitulo:"XXII - Dos Juramentos Legais e dos Votos",pergunta:"Segundo a Se\xE7\xE3o III, ao prestar um juramento, a pessoa deve obrigar-se:",alternativas:["Por qualquer promessa feita sob press\xE3o social, mesmo sem plena convic\xE7\xE3o pessoal","Somente por aquilo que \xE9 justo e bom, e que tem condi\xE7\xF5es reais e resolu\xE7\xE3o firme de cumprir","Somente diante de testemunhas eclesi\xE1sticas, sem necessidade de convic\xE7\xE3o \xEDntima da verdade","Por qualquer coisa solicitada pela autoridade legal, independentemente de ser justa ou n\xE3o","Apenas por compromissos religiosos, sendo os civis dispensados dessa exig\xEAncia de sinceridade"],respostaCorreta:"Somente por aquilo que \xE9 justo e bom, e que tem condi\xE7\xF5es reais e resolu\xE7\xE3o firme de cumprir",explicacao:"Se\xE7\xE3o III: deve-se jurar 't\xE3o somente por aquilo que \xE9 justo e bom... e por aquilo que pode e est\xE1 resolvido a cumprir'."},{id:2,capitulo:"XXIX - Da Ceia do Senhor",pergunta:"Segundo a Se\xE7\xE3o VIII, o que ocorre quando pessoas ignorantes ou \xEDmpias recebem exteriormente os elementos da Ceia?",alternativas:["Anulam automaticamente a validade do sacramento para toda a congrega\xE7\xE3o presente, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","Recebem apenas uma b\xEAn\xE7\xE3o simb\xF3lica menor, sem qualquer consequ\xEAncia espiritual negativa, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","Ficam isentos de responsabilidade, j\xE1 que a efic\xE1cia do rito n\xE3o depende do receptor, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o","Recebem plenamente a gra\xE7a sacramental, independentemente de sua condi\xE7\xE3o espiritual interior, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional","N\xE3o recebem a coisa significada, mas, por sua indigna participa\xE7\xE3o, tornam-se r\xE9us do corpo e do sangue do Senhor para sua pr\xF3pria condena\xE7\xE3o"],respostaCorreta:"N\xE3o recebem a coisa significada, mas, por sua indigna participa\xE7\xE3o, tornam-se r\xE9us do corpo e do sangue do Senhor para sua pr\xF3pria condena\xE7\xE3o",explicacao:"Se\xE7\xE3o VIII: os indignos 'n\xE3o recebem a coisa por eles significada, mas... tornam-se r\xE9us do corpo e do sangue do Senhor para a sua pr\xF3pria condena\xE7\xE3o'."},{id:3,capitulo:"XXVIII - Do Batismo",pergunta:"Segundo a Se\xE7\xE3o V, a Confiss\xE3o evita afirmar tanto que a regenera\xE7\xE3o \xE9 imposs\xEDvel sem o batismo quanto que todo batizado \xE9 necessariamente regenerado. Que erro exatamente essa formula\xE7\xE3o busca evitar?",alternativas:["A ideia de que o batismo deveria ser repetido sempre que o crente pecar gravemente, divergindo do que a se\xE7\xE3o afirma de modo expl\xEDcito, ideia que o texto da Confiss\xE3o, lido em conjunto, n\xE3o sustenta","A nega\xE7\xE3o completa de qualquer rela\xE7\xE3o espiritual real entre o sinal e a gra\xE7a significada, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o","A afirma\xE7\xE3o de que o batismo de crian\xE7as \xE9 ileg\xEDtimo, por n\xE3o haver profiss\xE3o pessoal de f\xE9, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","A confus\xE3o entre o sinal sacramental e a coisa significada, evitando tanto a neglig\xEAncia do batismo quanto sua absolutiza\xE7\xE3o como meio autom\xE1tico de regenera\xE7\xE3o","A rejei\xE7\xE3o da validade do batismo administrado por ministros n\xE3o ordenados formalmente, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo"],respostaCorreta:"A confus\xE3o entre o sinal sacramental e a coisa significada, evitando tanto a neglig\xEAncia do batismo quanto sua absolutiza\xE7\xE3o como meio autom\xE1tico de regenera\xE7\xE3o",explicacao:"Se\xE7\xE3o V evita tanto a neglig\xEAncia do sacramento quanto sua absolutiza\xE7\xE3o m\xE1gica (regenera\xE7\xE3o batismal autom\xE1tica): 'a gra\xE7a e a salva\xE7\xE3o n\xE3o se acham t\xE3o inseparavelmente ligadas com ela, que sem ela ningu\xE9m possa ser regenerado e salvo'."},{id:4,capitulo:"XII - Da Ado\xE7\xE3o",pergunta:"Segundo o Cap\xEDtulo XII, a gra\xE7a da ado\xE7\xE3o concede aos justificados, entre outras coisas, acesso confiante ao trono da gra\xE7a e o direito de clamar 'Abba, Pai'. Qual afirma\xE7\xE3o \xE9 incompat\xEDvel com o restante do cap\xEDtulo?",alternativas:["Os adotados jamais s\xE3o abandonados por Deus, permanecendo selados para o dia da reden\xE7\xE3o","Os adotados, uma vez recebidos, nunca mais ser\xE3o corrigidos ou disciplinados por Deus como um pai corrige seus filhos","Os adotados recebem o Esp\xEDrito de ado\xE7\xE3o e s\xE3o tratados com comisera\xE7\xE3o, prote\xE7\xE3o e provis\xE3o, como por um pai","Os adotados recebem sobre si o nome de filhos de Deus, gozando da liberdade e dos privil\xE9gios que lhes pertencem","Os adotados herdam as promessas, como herdeiros da eterna salva\xE7\xE3o"],respostaCorreta:"Os adotados, uma vez recebidos, nunca mais ser\xE3o corrigidos ou disciplinados por Deus como um pai corrige seus filhos",explicacao:"O cap\xEDtulo afirma expressamente que os adotados 's\xE3o tratados com comisera\xE7\xE3o, protegidos, providos e por ele corrigidos, como por um pai' \u2014 a corre\xE7\xE3o paterna continua fazendo parte da ado\xE7\xE3o."},{id:5,capitulo:"XXIV - Do Matrim\xF4nio e do Div\xF3rcio",pergunta:"Segundo a Se\xE7\xE3o III, \xE9 dever dos crist\xE3os casar somente no Senhor. Qual restri\xE7\xE3o a Confiss\xE3o explicitamente recomenda quanto \xE0 escolha do c\xF4njuge?",alternativas:["Casar somente com pessoas aprovadas previamente por um conc\xEDlio eclesi\xE1stico regional, ideia que o texto da Confiss\xE3o, lido em conjunto, n\xE3o sustenta","Casar apenas ap\xF3s um per\xEDodo m\xEDnimo formal de noivado supervisionado pela congrega\xE7\xE3o, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s","N\xE3o casar com infi\xE9is, papistas ou outros id\xF3latras, nem unir-se desigualmente a pessoas notoriamente \xEDmpias ou que sustentem heresias perniciosas","Casar exclusivamente com pessoas da mesma nacionalidade, por raz\xF5es de estabilidade cultural do lar, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional","Casar apenas dentro da pr\xF3pria denomina\xE7\xE3o local, sendo proibido o casamento entre presbiterianos e outros protestantes, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o"],respostaCorreta:"N\xE3o casar com infi\xE9is, papistas ou outros id\xF3latras, nem unir-se desigualmente a pessoas notoriamente \xEDmpias ou que sustentem heresias perniciosas",explicacao:"Se\xE7\xE3o III recomenda n\xE3o casar com infi\xE9is, papistas ou id\xF3latras, nem unir-se desigualmente a \xEDmpios not\xF3rios ou hereges \u2014 sem, contudo, proibir o casamento entre denomina\xE7\xF5es protestantes distintas."},{id:6,capitulo:"II - De Deus e da Sant\xEDssima Trindade",pergunta:"Segundo a Se\xE7\xE3o III, de quem procede eternamente o Esp\xEDrito Santo?",alternativas:["Somente do Pai, sendo o Filho apenas testemunha desse ato eterno de prociss\xE3o","Somente do Filho, recebendo o Pai o Esp\xEDrito posteriormente por comunica\xE7\xE3o","Do Pai, do Filho e da Igreja reunida em conc\xEDlio universal","De si mesmo, de modo absolutamente independente das outras duas pessoas","Do Pai e do Filho"],respostaCorreta:"Do Pai e do Filho",explicacao:"Se\xE7\xE3o III segue a cl\xE1usula filioque: 'o Esp\xEDrito Santo \xE9 eternamente procedente do Pai e do Filho' \u2014 o que difere da posi\xE7\xE3o ortodoxa oriental de prociss\xE3o apenas do Pai."},{id:7,capitulo:"XXXII - Do Estado do Homem depois da Morte e da Ressurrei\xE7\xE3o dos Mortos",pergunta:"Segundo a Se\xE7\xE3o I, al\xE9m do c\xE9u e do inferno para as almas separadas do corpo, quantos outros lugares intermedi\xE1rios as Escrituras reconhecem, segundo a Confiss\xE3o?",alternativas:["Um lugar espec\xEDfico reservado \xE0s crian\xE7as n\xE3o batizadas, distinto do c\xE9u e do inferno","Um estado intermedi\xE1rio de sono inconsciente da alma, \xE0 espera do ju\xEDzo final","Um lugar de espera para os que nunca ouviram o Evangelho, distinto dos dois destinos finais","Nenhum outro lugar al\xE9m destes dois \xE9 reconhecido pelas Escrituras","Um terceiro lugar de purifica\xE7\xE3o tempor\xE1ria, para as almas que morrem em estado imperfeito de gra\xE7a"],respostaCorreta:"Nenhum outro lugar al\xE9m destes dois \xE9 reconhecido pelas Escrituras",explicacao:"Se\xE7\xE3o I encerra afirmando que, 'al\xE9m destes dois lugares destinados \xE0s almas separadas de seus respectivos corpos as Escrituras n\xE3o reconhecem nenhum outro lugar' \u2014 rejeitando implicitamente a doutrina do purgat\xF3rio."},{id:8,capitulo:"X - Da Voca\xE7\xE3o Eficaz",pergunta:"Segundo a Se\xE7\xE3o IV, qual \xE9 a posi\xE7\xE3o da Confiss\xE3o sobre a possibilidade de salva\xE7\xE3o para os que nunca professam a religi\xE3o crist\xE3, mesmo vivendo conforme a luz da natureza?",alternativas:["Nega essa possibilidade, considerando 'muito pernicioso e detest\xE1vel' afirmar que tais pessoas podem ser salvas por outro meio","Deixa a quest\xE3o em aberto, sem qualquer posicionamento definido sobre o destino eterno dessas pessoas","Afirma que podem ser salvos se viverem de boa consci\xEAncia segundo a luz da natureza que possuem, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","Afirma que ser\xE3o salvos automaticamente, por n\xE3o terem tido acesso ao Evangelho, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo","Condiciona sua salva\xE7\xE3o exclusivamente \xE0 sinceridade da pr\xE1tica religiosa que seguem, divergindo do que a se\xE7\xE3o afirma de modo expl\xEDcito"],respostaCorreta:"Nega essa possibilidade, considerando 'muito pernicioso e detest\xE1vel' afirmar que tais pessoas podem ser salvas por outro meio",explicacao:"Se\xE7\xE3o IV rejeita explicitamente a ideia de salva\xE7\xE3o por fidelidade \xE0 luz da natureza fora de Cristo, chamando essa asser\xE7\xE3o de 'muito perniciosa e detest\xE1vel'."},{id:9,capitulo:"XXV - Da Igreja",pergunta:"Segundo a Se\xE7\xE3o II, a Igreja Vis\xEDvel sob o Evangelho, em contraste com a Igreja sob a Lei antiga, \xE9 caracterizada por:",alternativas:["N\xE3o ser restrita a uma \xFAnica na\xE7\xE3o, mas abranger todos os que professam a verdadeira religi\xE3o em todo o mundo, com seus filhos","Coincidir exatamente com a Igreja invis\xEDvel, sem qualquer possibilidade de mistura ou erro, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo","Excluir formalmente os filhos dos crentes at\xE9 que professem pessoalmente a f\xE9 na idade adulta, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s","Ser definida exclusivamente por crit\xE9rios \xE9tnicos e territoriais, como a antiga na\xE7\xE3o de Israel, tal como sustentado por correntes teol\xF3gicas distintas da reformada","Ser restrita a uma na\xE7\xE3o eleita espec\xEDfica, do mesmo modo como ocorria sob a antiga alian\xE7a, ideia que o texto da Confiss\xE3o, lido em conjunto, n\xE3o sustenta"],respostaCorreta:"N\xE3o ser restrita a uma \xFAnica na\xE7\xE3o, mas abranger todos os que professam a verdadeira religi\xE3o em todo o mundo, com seus filhos",explicacao:"Se\xE7\xE3o II: a Igreja Vis\xEDvel sob o Evangelho n\xE3o \xE9 'restrita a uma na\xE7\xE3o, como antes sob a Lei', mas abrange todos os que professam a verdadeira religi\xE3o pelo mundo inteiro, com seus filhos."},{id:10,capitulo:"Geral - Nota Hist\xF3rica",pergunta:"Segundo a Nota Hist\xF3rica, em qual cidade e local se reuniu a Assembleia de Westminster?",alternativas:["Na Catedral de Notre Dame, em Paris, sob prote\xE7\xE3o do rei da Fran\xE7a","Na Universidade de Oxford, por convoca\xE7\xE3o da Coroa inglesa","No Vaticano, por ocasi\xE3o de um conc\xEDlio ecum\xEAnico convocado pelo papa","Em uma sala da Abadia de Westminster, em Londres","No Pal\xE1cio de Genebra, sob a presid\xEAncia direta de Jo\xE3o Calvino"],respostaCorreta:"Em uma sala da Abadia de Westminster, em Londres",explicacao:"Nota Hist\xF3rica: o Conc\xEDlio reuniu-se 'em uma das salas da Abadia de Westminster, na cidade de Londres'."},{id:11,capitulo:"XXVII - Dos Sacramentos",pergunta:"Segundo o Cap\xEDtulo XXVII, quantos e quais s\xE3o os sacramentos ordenados por Cristo no Evangelho, em contraste com o n\xFAmero reconhecido pela tradi\xE7\xE3o cat\xF3lica romana?",alternativas:["Tr\xEAs: o Batismo, a Santa Ceia e a Confirma\xE7\xE3o","Cinco, excluindo apenas a extrema-un\xE7\xE3o e a ordem sacerdotal da lista tradicional","Um \xFAnico sacramento central, do qual o Batismo e a Ceia s\xE3o apenas express\xF5es simb\xF3licas","Dois: o Batismo e a Santa Ceia","Sete, incluindo confirma\xE7\xE3o, penit\xEAncia, un\xE7\xE3o dos enfermos, ordem e matrim\xF4nio"],respostaCorreta:"Dois: o Batismo e a Santa Ceia",explicacao:"Se\xE7\xE3o IV: 'H\xE1 s\xF3 dois sacramentos ordenados por Cristo, nosso Senhor, no Evangelho - O Batismo e a Santa Ceia' \u2014 em contraste com os sete sacramentos da tradi\xE7\xE3o cat\xF3lica romana."},{id:12,capitulo:"XXXIII - Do Ju\xEDzo Final",pergunta:"Segundo a Se\xE7\xE3o I, al\xE9m de todas as pessoas que viveram na terra, quem mais comparecer\xE1 para ser julgado no dia determinado por Deus?",alternativas:["Somente os seres humanos que morreram sem qualquer forma de f\xE9 religiosa declarada","Somente as pessoas que viveram ap\xF3s a primeira vinda de Cristo ao mundo","Os anjos ap\xF3statas","Apenas os l\xEDderes religiosos respons\xE1veis pela condu\xE7\xE3o espiritual de cada gera\xE7\xE3o","Nenhum outro ser al\xE9m dos seres humanos, j\xE1 que os anjos n\xE3o est\xE3o sujeitos a ju\xEDzo"],respostaCorreta:"Os anjos ap\xF3statas",explicacao:"Se\xE7\xE3o I: 'n\xE3o somente ser\xE3o julgados os anjos ap\xF3statas, mas tamb\xE9m todas as pessoas que tiverem vivido sobre a terra'."},{id:13,capitulo:"VII - Do Pacto de Deus com o Homem",pergunta:"Segundo a Se\xE7\xE3o VI, qual \xE9 a rela\xE7\xE3o entre o pacto administrado sob a Lei (Velho Testamento) e o pacto administrado sob o Evangelho (Novo Testamento)?",alternativas:["S\xE3o o mesmo pacto da gra\xE7a em subst\xE2ncia, variando apenas quanto \xE0 forma e ao modo de administra\xE7\xE3o","O pacto do Velho Testamento era de obras, sendo totalmente substitu\xEDdo por um pacto de gra\xE7a no Novo","S\xE3o dois pactos distintos e de subst\xE2ncia diferente, sendo o segundo uma corre\xE7\xE3o do primeiro","O pacto do Novo Testamento anula retroativamente a efic\xE1cia salv\xEDfica do pacto administrado antes de Cristo","Cada dispensa\xE7\xE3o b\xEDblica constitui um pacto pr\xF3prio e juridicamente independente dos demais"],respostaCorreta:"S\xE3o o mesmo pacto da gra\xE7a em subst\xE2ncia, variando apenas quanto \xE0 forma e ao modo de administra\xE7\xE3o",explicacao:"Se\xE7\xE3o VI: 'N\xE3o h\xE1, pois, dois pactos de gra\xE7a diferentes em subst\xE2ncia mas um e o mesmo sob v\xE1rias dispensa\xE7\xF5es' \u2014 posi\xE7\xE3o que se distingue de esquemas dispensacionalistas que multiplicam pactos distintos."},{id:14,capitulo:"XXIX - Da Ceia do Senhor",pergunta:"Segundo a Se\xE7\xE3o VII, como Cristo est\xE1 presente na Ceia do Senhor, segundo a Confiss\xE3o \u2014 em contraste tanto com a transubstancia\xE7\xE3o quanto com um memorialismo puramente simb\xF3lico?",alternativas:["Espiritual e realmente presente \xE0 f\xE9 dos crentes, n\xE3o estando corporal ou carnalmente nos elementos, com eles ou sob eles","Presente corporalmente nos pr\xF3prios elementos, embora sua subst\xE2ncia permane\xE7a oculta sob as apar\xEAncias de p\xE3o e vinho","Presente fisicamente 'com, em e sob' os elementos, unindo-se a eles sem altera\xE7\xE3o de sua subst\xE2ncia","Presente apenas como lembran\xE7a mental do sacrif\xEDcio passado, sem qualquer comunica\xE7\xE3o espiritual real e presente","Ausente da ordenan\xE7a, sendo a Ceia apenas um ato comunit\xE1rio de solidariedade entre os crentes, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s"],respostaCorreta:"Espiritual e realmente presente \xE0 f\xE9 dos crentes, n\xE3o estando corporal ou carnalmente nos elementos, com eles ou sob eles",explicacao:"Se\xE7\xE3o VII afirma presen\xE7a real, mas espiritual, recebida pela f\xE9 \u2014 posi\xE7\xE3o intermedi\xE1ria entre a transubstancia\xE7\xE3o cat\xF3lica, a consubstancia\xE7\xE3o luterana ('com, em e sob') e o memorialismo zwingliano."},{id:15,capitulo:"XVII - Da Perseveran\xE7a dos Santos",pergunta:"Segundo a Se\xE7\xE3o II, sobre o que se funda, em \xFAltima inst\xE2ncia, a certeza da perseveran\xE7a dos santos \u2014 em contraste com uma leitura que a funda no livre-arb\xEDtrio humano?",alternativas:["Na disciplina eclesi\xE1stica, que impede formalmente a apostasia dos membros batizados, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o","No compromisso cont\xEDnuo de boas obras, que sustenta e renova o estado de gra\xE7a a cada momento, ideia que o texto da Confiss\xE3o, lido em conjunto, n\xE3o sustenta","Na intensidade da experi\xEAncia de convers\xE3o inicial, medida subjetivamente pelo pr\xF3prio crente, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","Na imutabilidade do decreto de elei\xE7\xE3o e na efic\xE1cia do m\xE9rito e da intercess\xE3o de Cristo, n\xE3o no livre-arb\xEDtrio dos santos","No livre-arb\xEDtrio humano, que, uma vez fortalecido pela gra\xE7a, garante por si s\xF3 a perseveran\xE7a final"],respostaCorreta:"Na imutabilidade do decreto de elei\xE7\xE3o e na efic\xE1cia do m\xE9rito e da intercess\xE3o de Cristo, n\xE3o no livre-arb\xEDtrio dos santos",explicacao:"Se\xE7\xE3o II: a perseveran\xE7a 'n\xE3o depende do livre arb\xEDtrio deles, mas da imutabilidade do decreto da elei\xE7\xE3o... da efic\xE1cia do m\xE9rito e intercess\xE3o de Jesus Cristo'."},{id:16,capitulo:"XXX - Das Censuras Eclesi\xE1sticas",pergunta:"Segundo a Se\xE7\xE3o IV, qual \xE9 a ordem progressiva de disciplina que os oficiais da Igreja devem seguir, conforme a natureza do crime e o dem\xE9rito da pessoa?",alternativas:["Exclus\xE3o imediata da Igreja, com possibilidade de repreens\xE3o apenas em caso de recurso","Suspens\xE3o do batismo dos filhos, seguida de repreens\xE3o e, por fim, multa pecuni\xE1ria","Advert\xEAncia p\xFAblica \xFAnica, sem qualquer grada\xE7\xE3o posterior de disciplina","Excomunh\xE3o imediata, seguida de eventual readmiss\xE3o ap\xF3s processo civil formal","Repreens\xE3o, suspens\xE3o do sacramento da Ceia do Senhor e exclus\xE3o da Igreja"],respostaCorreta:"Repreens\xE3o, suspens\xE3o do sacramento da Ceia do Senhor e exclus\xE3o da Igreja",explicacao:"Se\xE7\xE3o IV estabelece uma ordem gradual: repreens\xE3o, suspens\xE3o da Ceia e, por fim, exclus\xE3o \u2014 n\xE3o a excomunh\xE3o imediata sem etapas pr\xE9vias."},{id:17,capitulo:"XXVI - Da Comunh\xE3o dos Santos",pergunta:"Segundo a Se\xE7\xE3o III, a comunh\xE3o que os santos t\xEAm uns com os outros e com Cristo:",alternativas:["Substitui qualquer forma de propriedade individual por um sistema de bens inteiramente comuns, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o","Implica participa\xE7\xE3o real na subst\xE2ncia divina, elevando os santos a uma condi\xE7\xE3o pr\xF3xima da de Cristo, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo","N\xE3o os torna participantes da subst\xE2ncia da Divindade nem iguais a Cristo em qualquer respeito, nem elimina o direito de propriedade individual","Exige a aboli\xE7\xE3o de toda propriedade privada entre os membros de uma mesma congrega\xE7\xE3o, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s","Estende-se apenas aos membros oficialmente ordenados, excluindo os leigos dessa comunh\xE3o espiritual, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo"],respostaCorreta:"N\xE3o os torna participantes da subst\xE2ncia da Divindade nem iguais a Cristo em qualquer respeito, nem elimina o direito de propriedade individual",explicacao:"Se\xE7\xE3o III nega expressamente tanto a diviniza\xE7\xE3o dos santos quanto qualquer forma de comunismo de bens: a comunh\xE3o espiritual 'n\xE3o destr\xF3i, nem de modo algum enfraquece o t\xEDtulo ou dom\xEDnio que cada homem tem sobre os seus bens'."},{id:18,capitulo:"II - De Deus e da Sant\xEDssima Trindade",pergunta:"Segundo a Se\xE7\xE3o II, qual destas formula\xE7\xF5es melhor reflete o ensino da Confiss\xE3o sobre a rela\xE7\xE3o entre Deus e sua gl\xF3ria manifestada nas criaturas?",alternativas:["Deus depende da resposta livre das criaturas para que sua gl\xF3ria se torne plenamente real","Deus criou o mundo por car\xEAncia interna de comunh\xE3o, suprida somente ap\xF3s a cria\xE7\xE3o do homem","A gl\xF3ria de Deus cresce proporcionalmente ao n\xFAmero de criaturas que o adoram ao longo da hist\xF3ria","Deus \xE9 todo-suficiente em si mesmo e apenas manifesta, sem aumentar, sua gl\xF3ria por meio das criaturas","Deus necessitava das criaturas para completar sua bem-aventuran\xE7a, embora n\xE3o dependesse delas para existir"],respostaCorreta:"Deus \xE9 todo-suficiente em si mesmo e apenas manifesta, sem aumentar, sua gl\xF3ria por meio das criaturas",explicacao:"Se\xE7\xE3o II: Deus \xE9 'todo suficiente em si e para si, pois n\xE3o precisa das criaturas... n\xE3o deriva delas gl\xF3ria alguma, mas somente manifesta a sua gl\xF3ria nelas'."},{id:19,capitulo:"XXIII - Do Magistrado Civil",pergunta:"Segundo a Se\xE7\xE3o III, qual \xE9 o limite da autoridade do magistrado civil em rela\xE7\xE3o \xE0 Igreja, segundo a Confiss\xE3o?",alternativas:["Tem autoridade para determinar o conte\xFAdo doutrin\xE1rio pregado pelos ministros de cada igreja, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","Est\xE1 inteiramente exclu\xEDdo de qualquer rela\xE7\xE3o com a prote\xE7\xE3o da liberdade religiosa, ideia que o texto da Confiss\xE3o, lido em conjunto, n\xE3o sustenta","Deve dar prefer\xEAncia oficial a uma \xFAnica denomina\xE7\xE3o crist\xE3, subordinando as demais a ela, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o","N\xE3o pode administrar a palavra e os sacramentos nem exercer o poder das chaves, mas deve proteger a liberdade dos eclesi\xE1sticos no exerc\xEDcio de suas fun\xE7\xF5es","Pode administrar diretamente os sacramentos em situa\xE7\xF5es de vac\xE2ncia pastoral prolongada, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo"],respostaCorreta:"N\xE3o pode administrar a palavra e os sacramentos nem exercer o poder das chaves, mas deve proteger a liberdade dos eclesi\xE1sticos no exerc\xEDcio de suas fun\xE7\xF5es",explicacao:"Se\xE7\xE3o III: o magistrado n\xE3o administra palavra e sacramentos nem o poder das chaves, mas deve proteger a liberdade dos eclesi\xE1sticos, 'sem dar prefer\xEAncia a qualquer denomina\xE7\xE3o crist\xE3 sobre as outras'."},{id:20,capitulo:"XI - Da Justifica\xE7\xE3o",pergunta:"A Se\xE7\xE3o II, sobre a f\xE9 nunca estar sozinha na pessoa justificada, mas ser acompanhada de outras gra\xE7as e obrar por amor, cita qual destas refer\xEAncias?",alternativas:["Gal. 3:8 (citada na Se\xE7\xE3o IV, sobre o decreto eterno de justificar os eleitos)","Rom. 3:24, 27-28 (citada na Se\xE7\xE3o I, sobre o fundamento da justifica\xE7\xE3o)","Rom. 4:25 (citada na Se\xE7\xE3o IV, sobre a ressurrei\xE7\xE3o de Cristo para a justifica\xE7\xE3o dos eleitos)","Gal. 5:6","Rom. 8:30 (citada na Se\xE7\xE3o I, sobre o encadeamento entre voca\xE7\xE3o e justifica\xE7\xE3o)"],respostaCorreta:"Gal. 5:6",explicacao:"A Se\xE7\xE3o II cita Gal. 5:6 ('a f\xE9 que opera por amor'); as demais alternativas pertencem a outras se\xE7\xF5es do mesmo cap\xEDtulo."},{id:21,capitulo:"XVIII - Da Certeza da Gra\xE7a e da Salva\xE7\xE3o",pergunta:"Segundo a Se\xE7\xE3o I, quem pode iludir-se v\xE3mente com falsas esperan\xE7as de estar em estado de gra\xE7a?",alternativas:["Qualquer crente genu\xEDno, sem exce\xE7\xE3o, pois a certeza de salva\xE7\xE3o \xE9 declarada inalcan\xE7\xE1vel nesta vida","Apenas os que rejeitam abertamente qualquer pr\xE1tica religiosa exterior","Os hip\xF3critas e os demais n\xE3o regenerados","Exclusivamente os que abandonam formalmente a comunh\xE3o de uma igreja local","Somente os que nunca ouviram a prega\xE7\xE3o do Evangelho em toda a vida"],respostaCorreta:"Os hip\xF3critas e os demais n\xE3o regenerados",explicacao:"Se\xE7\xE3o I distingue a falsa esperan\xE7a dos hip\xF3critas da certeza leg\xEDtima acess\xEDvel aos que verdadeiramente creem e amam a Cristo com sinceridade."},{id:22,capitulo:"XXXII - Do Estado do Homem depois da Morte e da Ressurrei\xE7\xE3o dos Mortos",pergunta:"A Se\xE7\xE3o I, sobre a promessa de Cristo ao ladr\xE3o arrependido na cruz como apoio \xE0 ideia de que a alma vai imediatamente para Deus, cita qual refer\xEAncia?",alternativas:["Fil. 3:21 (citada na Se\xE7\xE3o III, sobre a semelhan\xE7a do corpo ressuscitado ao de Cristo)","At. 13:36 (citada na mesma se\xE7\xE3o, mas referente \xE0 corrup\xE7\xE3o do corpo de Davi, n\xE3o \xE0 promessa ao ladr\xE3o)","At. 24:15 (citada na Se\xE7\xE3o III, sobre a ressurrei\xE7\xE3o dos justos e injustos)","Luc. 23:43","I Tess. 4:17 (citada na Se\xE7\xE3o II, sobre os vivos que ser\xE3o mudados no \xFAltimo dia)"],respostaCorreta:"Luc. 23:43",explicacao:"A Se\xE7\xE3o I cita Luc. 23:43 especificamente para a promessa 'hoje estar\xE1s comigo no para\xEDso'; as demais alternativas pertencem a outras partes do cap\xEDtulo."},{id:23,capitulo:"VI - Da Queda do Homem, do Pecado e do seu Castigo",pergunta:"Segundo a Se\xE7\xE3o III, como o pecado de Ad\xE3o se relaciona com toda a sua posteridade, segundo a Confiss\xE3o \u2014 em contraste com uma vis\xE3o que nega a imputa\xE7\xE3o do pecado original?",alternativas:["Cada pessoa nasce moralmente neutra, herdando apenas a mortalidade f\xEDsica, sem qualquer imputa\xE7\xE3o de culpa, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","A corrup\xE7\xE3o \xE9 adquirida somente pela imita\xE7\xE3o do mau exemplo, n\xE3o por transmiss\xE3o da pr\xF3pria natureza, ideia que o texto da Confiss\xE3o, lido em conjunto, n\xE3o sustenta","O delito do pecado de Ad\xE3o foi imputado aos seus descendentes, e a morte em pecado e a natureza corrompida foram transmitidas pela gera\xE7\xE3o ordin\xE1ria","A posteridade herda a inclina\xE7\xE3o ao mal, mas n\xE3o qualquer imputa\xE7\xE3o legal de culpa, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o","A culpa de Ad\xE3o afeta apenas os que conscientemente ratificam o pecado dele por atos pr\xF3prios, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo"],respostaCorreta:"O delito do pecado de Ad\xE3o foi imputado aos seus descendentes, e a morte em pecado e a natureza corrompida foram transmitidas pela gera\xE7\xE3o ordin\xE1ria",explicacao:"Se\xE7\xE3o III afirma tanto a imputa\xE7\xE3o do delito quanto a transmiss\xE3o real da natureza corrompida \u2014 posi\xE7\xE3o que se op\xF5e a leituras pelagianas ou semipelagianas do pecado original."},{id:24,capitulo:"XIV - Da F\xE9 Salvadora",pergunta:"A Se\xE7\xE3o I, sobre a f\xE9 ser aumentada e fortalecida pelo minist\xE9rio da palavra, pelos sacramentos e pela ora\xE7\xE3o, cita qual destas refer\xEAncias?",alternativas:["Rom. 4:19-20 (citada na Se\xE7\xE3o III, sobre os diferentes graus da f\xE9)","Heb. 11:13 (citada na Se\xE7\xE3o II, sobre os crentes abra\xE7arem as promessas de longe)","Heb. 6:11, 12 (citada na Se\xE7\xE3o III, sobre a plena seguran\xE7a em Cristo)","Rom. 10:14, 17","At. 24:14 (citada na Se\xE7\xE3o II, sobre crer em tudo o que \xE9 revelado na Escritura)"],respostaCorreta:"Rom. 10:14, 17",explicacao:"A Se\xE7\xE3o I cita Rom. 10:14, 17, sobre a f\xE9 vir pelo ouvir a palavra; as demais pertencem a outras se\xE7\xF5es do mesmo cap\xEDtulo."},{id:25,capitulo:"XI - Da Justifica\xE7\xE3o",pergunta:"Segundo a Se\xE7\xE3o V, um crente verdadeiramente justificado pode, ao pecar, decair totalmente do estado de justifica\xE7\xE3o?",alternativas:["Sim, sendo restaurado ao estado de justifica\xE7\xE3o somente ap\xF3s novo batismo, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","N\xE3o \xE9 abordado nesta se\xE7\xE3o, que trata apenas da justifica\xE7\xE3o inicial, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o","N\xE3o; ainda que possa incorrer no paternal desagrado de Deus e ficar privado da luz do seu rosto at\xE9 se humilhar e arrepender","Sim, mas apenas se o pecado for considerado mortal segundo a tradi\xE7\xE3o da Igreja, divergindo do que a se\xE7\xE3o afirma de modo expl\xEDcito","Sim; cada pecado grave exige uma nova justifica\xE7\xE3o formal, distinta da primeira, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional"],respostaCorreta:"N\xE3o; ainda que possa incorrer no paternal desagrado de Deus e ficar privado da luz do seu rosto at\xE9 se humilhar e arrepender",explicacao:"Se\xE7\xE3o V: o justificado 'nunca poder\xE3o decair do estado de justifica\xE7\xE3o', embora possa perder temporariamente a comunh\xE3o consciente com Deus por causa do pecado."},{id:26,capitulo:"XXXIII - Do Ju\xEDzo Final",pergunta:"A Se\xE7\xE3o II, sobre o fim que Deus tem em vista ao determinar o dia do ju\xEDzo \u2014 manifestar a gl\xF3ria da sua miseric\xF3rdia e da sua justi\xE7a \u2014, cita qual destas refer\xEAncias?",alternativas:["Ec. 12:14 (citada na Se\xE7\xE3o I, sobre a presta\xE7\xE3o de contas de pensamentos e obras)","Mat. 12:36-37 (citada na Se\xE7\xE3o I, sobre a conta a ser dada por toda palavra ociosa)","Mat. 25:31-34","II Ped. 2:4 (citada na Se\xE7\xE3o I, sobre o ju\xEDzo dos anjos ap\xF3statas)","At. 17:31 (citada na Se\xE7\xE3o I, sobre Deus ter determinado um dia para julgar o mundo)"],respostaCorreta:"Mat. 25:31-34",explicacao:"A Se\xE7\xE3o II cita Mat. 25:31-34, entre outras, sobre os justos indo para a vida eterna; as demais alternativas pertencem \xE0 Se\xE7\xE3o I do mesmo cap\xEDtulo."},{id:27,capitulo:"XXXI - Dos S\xEDnodos e Conc\xEDlios",pergunta:"Segundo a Se\xE7\xE3o III, qual \xE9 a autoridade final atribu\xEDda pela Confiss\xE3o aos s\xEDnodos e conc\xEDlios, mesmo os gerais, desde os tempos apost\xF3licos?",alternativas:["Perdem toda utilidade ou autoridade, n\xE3o devendo ser convocados desde a conclus\xE3o do c\xE2non, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo","T\xEAm autoridade equivalente \xE0 da pr\xF3pria Escritura, uma vez formalmente ratificados, divergindo do que a se\xE7\xE3o afirma de modo expl\xEDcito","Podem errar, e muitos t\xEAm errado, n\xE3o devendo constituir regra absoluta de f\xE9 e pr\xE1tica, mas podendo servir de aux\xEDlio","S\xE3o infal\xEDveis apenas quando decidem por unanimidade absoluta entre todos os presentes, tal como sustentado por correntes teol\xF3gicas distintas da reformada","S\xE3o infal\xEDveis sempre que re\xFAnem representantes de todas as igrejas reformadas do mundo, ideia que o texto da Confiss\xE3o, lido em conjunto, n\xE3o sustenta"],respostaCorreta:"Podem errar, e muitos t\xEAm errado, n\xE3o devendo constituir regra absoluta de f\xE9 e pr\xE1tica, mas podendo servir de aux\xEDlio",explicacao:"Se\xE7\xE3o III: s\xEDnodos e conc\xEDlios 'podem errar, e muitos t\xEAm errado', n\xE3o constituindo regra de f\xE9 e pr\xE1tica, mas apenas aux\xEDlio subordinado \xE0 Escritura."},{id:28,capitulo:"Geral - Nota Hist\xF3rica",pergunta:"Segundo a Nota Hist\xF3rica, a Confiss\xE3o de Westminster \xE9 descrita como pertencente a qual per\xEDodo de produ\xE7\xE3o confessional, compar\xE1vel em import\xE2ncia apenas ao per\xEDodo dos credos ecum\xEAnicos dos s\xE9culos IV e V?",alternativas:["O per\xEDodo medieval escol\xE1stico, entre os s\xE9culos XII e XIII","O per\xEDodo do Grande Cisma do Oriente, no s\xE9culo XI","O per\xEDodo da Reforma protestante","O per\xEDodo iluminista, entre os s\xE9culos XVII e XVIII","O per\xEDodo da patr\xEDstica p\xF3s-nicena, entre os s\xE9culos V e VI"],respostaCorreta:"O per\xEDodo da Reforma protestante",explicacao:"Nota Hist\xF3rica: 'o segundo [per\xEDodo] sincroniza com o per\xEDodo da Reforma', sendo a Confiss\xE3o de Westminster 'a \xFAltima das confiss\xF5es formuladas durante o per\xEDodo da Reforma'."},{id:29,capitulo:"III - Dos Eternos Decretos de Deus",pergunta:"Segundo a Se\xE7\xE3o V, qual \xE9 o fundamento da elei\xE7\xE3o, em contraste com uma leitura arminiana da doutrina?",alternativas:["A elei\xE7\xE3o funda-se na presci\xEAncia divina da f\xE9 que cada indiv\xEDduo exerceria livremente diante do Evangelho","A elei\xE7\xE3o funda-se em uma combina\xE7\xE3o entre m\xE9rito congruente e gra\xE7a preveniente, divergindo do que a se\xE7\xE3o afirma de modo expl\xEDcito","A elei\xE7\xE3o funda-se somente na gra\xE7a e no amor livres de Deus, sem qualquer previs\xE3o de f\xE9, obras ou perseveran\xE7a na criatura","A elei\xE7\xE3o funda-se na perseveran\xE7a que Deus previu que o indiv\xEDduo manteria at\xE9 o fim da vida, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo","A elei\xE7\xE3o funda-se na coopera\xE7\xE3o pr\xE9via entre a gra\xE7a oferecida e a resposta humana antecipada, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o"],respostaCorreta:"A elei\xE7\xE3o funda-se somente na gra\xE7a e no amor livres de Deus, sem qualquer previs\xE3o de f\xE9, obras ou perseveran\xE7a na criatura",explicacao:"Se\xE7\xE3o V: Deus escolheu os eleitos 'de sua mera e livre gra\xE7a e amor, e n\xE3o por previs\xE3o de f\xE9, ou de boas obras... como condi\xE7\xE3o ou causa' \u2014 rejeitando explicitamente o esquema arminiano da elei\xE7\xE3o condicional."},{id:30,capitulo:"XXVII - Dos Sacramentos",pergunta:"A Se\xE7\xE3o IV, sobre haver s\xF3 dois sacramentos ordenados por Cristo no Evangelho, cita qual destas refer\xEAncias?",alternativas:["Gen. 17:10 (citada na Se\xE7\xE3o II, sobre a rela\xE7\xE3o sacramental entre sinal e coisa significada)","Mat. 28:19","I Cor. 10:1-4 (citada na Se\xE7\xE3o V, sobre os sacramentos do Velho Testamento)","Rom. 6:11 (citada na Se\xE7\xE3o I, sobre os sacramentos como sinais do pacto da gra\xE7a)","I Ped. 3:21 (citada na Se\xE7\xE3o III, sobre a efic\xE1cia dos sacramentos n\xE3o depender do rito)"],respostaCorreta:"Mat. 28:19",explicacao:"A Se\xE7\xE3o IV cita Mat. 28:19, I Cor. 11:20, 23-34 e Heb. 5:4; as demais alternativas pertencem a outras se\xE7\xF5es do cap\xEDtulo."},{id:31,capitulo:"XXIX - Da Ceia do Senhor",pergunta:"Segundo a Se\xE7\xE3o II, a Confiss\xE3o rejeita explicitamente qual entendimento da Ceia como um novo sacrif\xEDcio oferecido pelos vivos e pelos mortos?",alternativas:["A distribui\xE7\xE3o da Ceia por ministros n\xE3o episcopalmente ordenados, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o","A recep\xE7\xE3o do c\xE1lice pelos leigos, por comprometer a unicidade do sacrif\xEDcio original","A pr\xE1tica de partir o p\xE3o em assembleia, por implicar repeti\xE7\xE3o indevida do sacrif\xEDcio de Cristo","A prega\xE7\xE3o da palavra de institui\xE7\xE3o antes da Ceia, por antecipar indevidamente o rito","O chamado sacrif\xEDcio da missa, por ser ofensivo ao \xFAnico e suficiente sacrif\xEDcio de Cristo na cruz"],respostaCorreta:"O chamado sacrif\xEDcio da missa, por ser ofensivo ao \xFAnico e suficiente sacrif\xEDcio de Cristo na cruz",explicacao:"Se\xE7\xE3o II: 'o chamado sacrif\xEDcio papal da missa \xE9 sobremodo ofensivo ao \xFAnico sacrif\xEDcio de Cristo' \u2014 a Ceia \xE9 comemora\xE7\xE3o, n\xE3o repeti\xE7\xE3o do sacrif\xEDcio."},{id:32,capitulo:"XXXII - Do Estado do Homem depois da Morte e da Ressurrei\xE7\xE3o dos Mortos",pergunta:"Segundo a Se\xE7\xE3o II, no \xFAltimo dia, os corpos dos mortos ser\xE3o ressuscitados:",alternativas:["Com os seus mesmos corpos, ainda que com qualidades diferentes, reunidos \xE0s suas almas para sempre","Somente os corpos dos eleitos ser\xE3o ressuscitados; os dos r\xE9probos permanecer\xE3o no p\xF3","Em uma forma corporal \xFAnica e id\xEAntica para todos, sem distin\xE7\xE3o entre justos e \xEDmpios","Com corpos totalmente novos e sem qualquer rela\xE7\xE3o de continuidade com os corpos anteriores","Apenas de forma espiritual, sem qualquer dimens\xE3o corporal na ressurrei\xE7\xE3o final"],respostaCorreta:"Com os seus mesmos corpos, ainda que com qualidades diferentes, reunidos \xE0s suas almas para sempre",explicacao:"Se\xE7\xE3o II: os mortos 'ser\xE3o ressuscitados com os seus mesmos corpos e n\xE3o outros, posto que com qualidades diferentes'."},{id:33,capitulo:"VIII - De Cristo o Mediador",pergunta:"Segundo a Se\xE7\xE3o VIII, como a salva\xE7\xE3o adquirida por Cristo \xE9 aplicada aos eleitos, em contraste com uma leitura que a torna meramente poss\xEDvel a todos indistintamente?",alternativas:["Cristo torna a salva\xE7\xE3o igualmente poss\xEDvel a todos os homens, cabendo \xE0 vontade humana decidir sua aplica\xE7\xE3o final, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s","Cristo aplica a salva\xE7\xE3o por meio exclusivo dos sacramentos, independentemente da f\xE9 pessoal, divergindo do que a se\xE7\xE3o afirma de modo expl\xEDcito","Cristo aplica a salva\xE7\xE3o de modo condicional, aguardando a coopera\xE7\xE3o humana em cada etapa do processo, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional","Cristo aplica e comunica com toda a certeza e efic\xE1cia a salva\xE7\xE3o a todos aqueles para os quais a adquiriu, persuadindo-os eficazmente pelo seu Esp\xEDrito","Cristo oferece a salva\xE7\xE3o de modo gen\xE9rico, sem qualquer efic\xE1cia particular garantida aos eleitos, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo"],respostaCorreta:"Cristo aplica e comunica com toda a certeza e efic\xE1cia a salva\xE7\xE3o a todos aqueles para os quais a adquiriu, persuadindo-os eficazmente pelo seu Esp\xEDrito",explicacao:"Se\xE7\xE3o VIII afirma a aplica\xE7\xE3o certa e eficaz da reden\xE7\xE3o adquirida \u2014 express\xE3o do princ\xEDpio reformado da reden\xE7\xE3o particular e eficaz."},{id:34,capitulo:"III - Dos Eternos Decretos de Deus",pergunta:"Segundo a Se\xE7\xE3o I, ao decretar livremente tudo quanto acontece, Deus:",alternativas:["Torna-se causa moral direta do pecado, ainda que sem culpa, por decretar sua ocorr\xEAncia, divergindo do que a se\xE7\xE3o afirma de modo expl\xEDcito","N\xE3o \xE9 o autor do pecado, nem \xE9 violentada a vontade da criatura, nem eliminada a conting\xEAncia das causas secund\xE1rias","Decreta apenas o bem, deixando o mal inteiramente fora do \xE2mbito do seu eterno conselho, tal como sustentado por correntes teol\xF3gicas distintas da reformada","Suspende temporariamente sua soberania sobre eventos contingentes, delegando-a \xE0s causas secund\xE1rias","Elimina toda conting\xEAncia genu\xEDna, tornando as causas secund\xE1rias meras apar\xEAncias sem efic\xE1cia real"],respostaCorreta:"N\xE3o \xE9 o autor do pecado, nem \xE9 violentada a vontade da criatura, nem eliminada a conting\xEAncia das causas secund\xE1rias",explicacao:"Se\xE7\xE3o I preserva simultaneamente a soberania absoluta do decreto e a integridade da vontade da criatura e das causas secund\xE1rias."},{id:35,capitulo:"XXVII - Dos Sacramentos",pergunta:"Segundo a Se\xE7\xE3o III, a efic\xE1cia da gra\xE7a significada nos sacramentos depende de qu\xEA \u2014 em contraste com uma leitura ex opere operato que a vincula ao ato ritual em si?",alternativas:["Da autoridade formal e da validade can\xF4nica da ordena\xE7\xE3o do ministro que os administra, divergindo do que a se\xE7\xE3o afirma de modo expl\xEDcito","Da obra do Esp\xEDrito e da palavra da institui\xE7\xE3o, e n\xE3o de qualquer poder inerente aos pr\xF3prios sacramentos ou da piedade de quem os administra","Do poder espiritual contido nos pr\xF3prios elementos materiais, uma vez devidamente consagrados, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional","Exclusivamente da piedade pessoal e da inten\xE7\xE3o reta do ministro que os administra, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","Da frequ\xEAncia com que a pessoa participa deles ao longo da vida crist\xE3, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o"],respostaCorreta:"Da obra do Esp\xEDrito e da palavra da institui\xE7\xE3o, e n\xE3o de qualquer poder inerente aos pr\xF3prios sacramentos ou da piedade de quem os administra",explicacao:"Se\xE7\xE3o III rejeita a efic\xE1cia autom\xE1tica (ex opere operato): a gra\xE7a depende 'da obra do Esp\xEDrito e da palavra da institui\xE7\xE3o', n\xE3o de poder inerente ao rito ou da piedade do ministro."},{id:36,capitulo:"XXVIII - Do Batismo",pergunta:"A Se\xE7\xE3o I, sobre o batismo como sinal e selo do pacto da gra\xE7a e da regenera\xE7\xE3o, cita qual destas refer\xEAncias?",alternativas:["At. 2:41 e 10:46-47 (citada na Se\xE7\xE3o III, sobre o modo de administra\xE7\xE3o do batismo)","Rom. 6:3-4","At. 10:47 e 8:36-38 (citada na Se\xE7\xE3o II, sobre a \xE1gua como elemento do batismo)","Luc. 7:30 (citada na Se\xE7\xE3o V, sobre o pecado de desprezar a ordenan\xE7a do batismo)","Gal. 3:9, 14 (citada na Se\xE7\xE3o IV, sobre os filhos de pais crentes serem batizados)"],respostaCorreta:"Rom. 6:3-4",explicacao:"A Se\xE7\xE3o I cita, entre outras, Rom. 6:3-4, sobre o batismo significar a uni\xE3o com Cristo em novidade de vida; as demais pertencem a outras se\xE7\xF5es do cap\xEDtulo."},{id:37,capitulo:"XIV - Da F\xE9 Salvadora",pergunta:"Segundo a Se\xE7\xE3o I, por qual meio a gra\xE7a da f\xE9 \xE9 ordinariamente operada e, em seguida, aumentada e fortalecida?",alternativas:["Pelo minist\xE9rio da palavra, sendo aumentada tamb\xE9m pela administra\xE7\xE3o dos sacramentos e pela ora\xE7\xE3o","Por experi\xEAncias m\xEDsticas diretas, independentes da prega\xE7\xE3o ou dos sacramentos","Por revela\xE7\xF5es extraordin\xE1rias concedidas individualmente a cada crente, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s","Exclusivamente pela participa\xE7\xE3o regular na Ceia do Senhor, sem rela\xE7\xE3o necess\xE1ria com a prega\xE7\xE3o","Por heran\xE7a familiar, sendo transmitida de pais para filhos independentemente do minist\xE9rio da palavra"],respostaCorreta:"Pelo minist\xE9rio da palavra, sendo aumentada tamb\xE9m pela administra\xE7\xE3o dos sacramentos e pela ora\xE7\xE3o",explicacao:"Se\xE7\xE3o I: a f\xE9 '\xE9 ordinariamente operada pelo minist\xE9rio da palavra; por esse minist\xE9rio, bem como pela administra\xE7\xE3o dos sacramentos e pela ora\xE7\xE3o, ela \xE9 aumentada e fortalecida'."},{id:38,capitulo:"X - Da Voca\xE7\xE3o Eficaz",pergunta:"Segundo a Se\xE7\xE3o II, na voca\xE7\xE3o eficaz, o papel do homem antes de ser vivificado pelo Esp\xEDrito \xE9 descrito como:",alternativas:["Parcialmente ativo, contribuindo com um m\xE9rito congruente que disp\xF5e Deus a agir, ideia que o texto da Confiss\xE3o, lido em conjunto, n\xE3o sustenta","Ativo desde o in\xEDcio, pois a vontade humana coopera com a gra\xE7a antes mesmo da regenera\xE7\xE3o","Determinante, j\xE1 que a voca\xE7\xE3o eficaz depende do consentimento pr\xE9vio da vontade humana","Irrelevante, pois a voca\xE7\xE3o eficaz ocorre sem qualquer rela\xE7\xE3o com a vontade humana, mesmo depois de vivificado","Inteiramente passivo, at\xE9 ser vivificado e renovado, quando ent\xE3o se habilita a responder \xE0 gra\xE7a oferecida"],respostaCorreta:"Inteiramente passivo, at\xE9 ser vivificado e renovado, quando ent\xE3o se habilita a responder \xE0 gra\xE7a oferecida",explicacao:"Se\xE7\xE3o II: o homem \xE9 'inteiramente passivo, at\xE9 que, vivificado e renovado pelo Esp\xEDrito Santo, fica habilitado a corresponder a ela'."},{id:39,capitulo:"VIII - De Cristo o Mediador",pergunta:"Segundo a Se\xE7\xE3o V, a obedi\xEAncia e o sacrif\xEDcio de Cristo satisfizeram plenamente a justi\xE7a do Pai. Qual formula\xE7\xE3o abaixo \xE9 incompat\xEDvel com essa se\xE7\xE3o?",alternativas:["A satisfa\xE7\xE3o de Cristo foi parcial, sendo completada pelos m\xE9ritos e penit\xEAncias dos pr\xF3prios crentes","A satisfa\xE7\xE3o foi oferecida uma s\xF3 vez, pelo Eterno Esp\xEDrito, sem necessidade de repeti\xE7\xE3o","A satisfa\xE7\xE3o de Cristo foi plena e \xFAnica, adquirindo reconcilia\xE7\xE3o e heran\xE7a perdur\xE1vel para os eleitos","A obedi\xEAncia de Cristo incluiu tanto a obedi\xEAncia ativa quanto a passiva, culminando no sacrif\xEDcio de si mesmo","A satisfa\xE7\xE3o de Cristo alcan\xE7ou plenamente aqueles que o Pai lhe deu, segundo o pacto eterno"],respostaCorreta:"A satisfa\xE7\xE3o de Cristo foi parcial, sendo completada pelos m\xE9ritos e penit\xEAncias dos pr\xF3prios crentes",explicacao:"A Se\xE7\xE3o V afirma satisfa\xE7\xE3o plena e \xFAnica por Cristo; a ideia de complemento por m\xE9ritos humanos \xE9 estranha ao texto e contraria a doutrina da satisfa\xE7\xE3o vic\xE1ria completa."},{id:40,capitulo:"I - Da Escritura Sagrada",pergunta:"Segundo a Se\xE7\xE3o IX, quando h\xE1 d\xFAvida sobre o sentido pleno de um texto b\xEDblico, a Confiss\xE3o prescreve que:",alternativas:["O texto obscuro deve ceder \xE0 tradi\xE7\xE3o patr\xEDstica sempre que esta apresentar leitura mais antiga","O texto obscuro deve ser interpretado livremente por cada crente, sem recurso a outros textos b\xEDblicos","O texto obscuro deve ser interpretado por outros textos que falem mais claramente sobre o mesmo assunto","O texto obscuro deve ser resolvido pela autoridade final do magist\xE9rio eclesi\xE1stico reunido em conc\xEDlio","O texto obscuro permanece propositalmente indecid\xEDvel, cabendo \xE0 raz\xE3o natural suprir o sentido"],respostaCorreta:"O texto obscuro deve ser interpretado por outros textos que falem mais claramente sobre o mesmo assunto",explicacao:"Se\xE7\xE3o IX: a Escritura interpreta a si mesma; textos obscuros s\xE3o esclarecidos por textos mais claros sobre o mesmo assunto (analogia da f\xE9)."},{id:41,capitulo:"XXXIV - Do Esp\xEDrito Santo",pergunta:"Segundo a Se\xE7\xE3o II, por meio de quem os autores da Sagrada Escritura foram levados a registrar infalivelmente a vontade de Deus?",alternativas:["Pela tradi\xE7\xE3o oral da comunidade, posteriormente sistematizada pelos conc\xEDlios","Pelo pr\xF3prio racioc\xEDnio humano, iluminado apenas indiretamente pela provid\xEAncia geral","Pelos anjos, que ditaram diretamente o texto aos escritores humanos","Pelo Esp\xEDrito Santo","Por Cristo pessoalmente, em apari\xE7\xF5es privadas a cada um dos autores b\xEDblicos"],respostaCorreta:"Pelo Esp\xEDrito Santo",explicacao:"Se\xE7\xE3o II: 'Por Ele os Profetas foram levados a falar a Palavra de Deus, e todos os autores da Sagrada Escritura foram inspirados a registrar de um modo infal\xEDvel a disposi\xE7\xE3o e a vontade de Deus'."},{id:42,capitulo:"I - Da Escritura Sagrada",pergunta:"A Se\xE7\xE3o V afirma que a certeza plena da autoridade divina da Escritura prov\xE9m, em \xFAltima inst\xE2ncia, da opera\xE7\xE3o interna do Esp\xEDrito Santo, e n\xE3o apenas do testemunho da Igreja. Qual refer\xEAncia \xE9 citada como apoio direto a essa se\xE7\xE3o?",alternativas:["G\xEAnesis 1:1","Salmos 23:1","I Jo\xE3o 2:20, 27","Apocalipse 21:1","Mateus 6:9-13"],respostaCorreta:"I Jo\xE3o 2:20, 27",explicacao:"Se\xE7\xE3o V cita I Tim. 3:15; I Jo\xE3o 2:20, 27; Jo\xE3o 16:13-14; I Cor. 2:10-12, referentes ao testemunho interno do Esp\xEDrito."},{id:43,capitulo:"I - Da Escritura Sagrada",pergunta:"Segundo a Se\xE7\xE3o VI, como a Confiss\xE3o trata a possibilidade de novas revela\xE7\xF5es do Esp\xEDrito complementarem a Escritura?",alternativas:["Aceita a tradi\xE7\xE3o apost\xF3lica n\xE3o escrita como fonte de igual autoridade, complementar \xE0 Escritura","Reserva a possibilidade de revela\xE7\xE3o cont\xEDnua exclusivamente aos ap\xF3stolos e seus sucessores diretos","Admite novas revela\xE7\xF5es do Esp\xEDrito, desde que confirmadas posteriormente por um conc\xEDlio ecum\xEAnico","Permite acr\xE9scimos doutrin\xE1rios sempre que confirmados pela experi\xEAncia religiosa da comunidade","Nega expressamente que algo se acrescente \xE0 Escritura, seja por novas revela\xE7\xF5es do Esp\xEDrito, seja por tradi\xE7\xF5es humanas"],respostaCorreta:"Nega expressamente que algo se acrescente \xE0 Escritura, seja por novas revela\xE7\xF5es do Esp\xEDrito, seja por tradi\xE7\xF5es humanas",explicacao:"Se\xE7\xE3o VI: '\xC0 Escritura nada se acrescentar\xE1 em tempo algum, nem por novas revela\xE7\xF5es do Esp\xEDrito, nem por tradi\xE7\xF5es dos homens'."},{id:44,capitulo:"XIX - Da Lei de Deus",pergunta:"Segundo a Se\xE7\xE3o II, os dez mandamentos, escritos em duas t\xE1buas no monte Sinai, dividem-se, segundo a Confiss\xE3o, em:",alternativas:["Tr\xEAs mandamentos para com Deus e sete para com o pr\xF3ximo, seguindo a divis\xE3o hebraica cl\xE1ssica","Todos os dez voltados igualmente e sem distin\xE7\xE3o para os deveres para com o pr\xF3ximo","Cinco mandamentos para cada t\xE1bua, distribu\xEDdos de modo sim\xE9trico entre Deus e o pr\xF3ximo","Quatro mandamentos que ensinam os deveres para com Deus e seis que ensinam os deveres para com o homem","Seis mandamentos para com Deus e quatro para com o homem, invertendo a divis\xE3o usual"],respostaCorreta:"Quatro mandamentos que ensinam os deveres para com Deus e seis que ensinam os deveres para com o homem",explicacao:"Se\xE7\xE3o II: 'os primeiros quatro mandamentos ensinam os nossos deveres para com Deus e os outros seis os nossos deveres para com o homem'."},{id:45,capitulo:"XVII - Da Perseveran\xE7a dos Santos",pergunta:"Segundo a Se\xE7\xE3o III, os verdadeiros santos, mesmo perseverando ao final, podem:",alternativas:["Permanecer sempre imunes a qualquer queda moral, em virtude da seguran\xE7a da elei\xE7\xE3o","Cair em graves pecados por algum tempo, incorrendo no desagrado de Deus e trazendo ju\xEDzos temporais sobre si","Perder totalmente a salva\xE7\xE3o, sendo readmitidos apenas por um novo ato de justifica\xE7\xE3o","Ser definitivamente exclu\xEDdos da comunh\xE3o da Igreja, ainda que permane\xE7am salvos diante de Deus","Cometer pecados graves sem qualquer consequ\xEAncia disciplinar, dada a certeza da perseveran\xE7a"],respostaCorreta:"Cair em graves pecados por algum tempo, incorrendo no desagrado de Deus e trazendo ju\xEDzos temporais sobre si",explicacao:"Se\xE7\xE3o III: os santos podem 'cair em graves pecados e por algum tempo continuar neles', incorrendo em desagrado divino e ju\xEDzos temporais, sem que isso signifique perda final da salva\xE7\xE3o."},{id:46,capitulo:"Geral - Estrutura da Confiss\xE3o",pergunta:"Segundo o texto final anexo ('Autoridade da Confiss\xE3o de F\xE9 e dos Catecismos'), qual \xE9 a rela\xE7\xE3o de autoridade que a Igreja Presbiteriana estabelece entre a Escritura e a pr\xF3pria Confiss\xE3o de F\xE9?",alternativas:["A Escritura \xE9 a suprema e infal\xEDvel regra de f\xE9 e pr\xE1tica; a Confiss\xE3o deriva toda a sua autoridade dela e a ela se subordina inteiramente","A Confiss\xE3o substitui, para fins pr\xE1ticos, a necessidade de recurso direto e constante \xE0 Escritura, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional","A Escritura e a Confiss\xE3o possuem autoridade igual e complementar, formando juntas a regra de f\xE9, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","A autoridade da Confiss\xE3o independe de sua conformidade com a Escritura, bastando o consenso eclesi\xE1stico, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o","A Escritura s\xF3 pode ser corretamente lida \xE0 luz da Confiss\xE3o, que funciona como norma superior a ela, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s"],respostaCorreta:"A Escritura \xE9 a suprema e infal\xEDvel regra de f\xE9 e pr\xE1tica; a Confiss\xE3o deriva toda a sua autoridade dela e a ela se subordina inteiramente",explicacao:"O texto final afirma que a Escritura \xE9 'a suprema e infal\xEDvel regra de f\xE9 e pr\xE1tica', e que a Confiss\xE3o 'dela deriva toda a sua autoridade e a ela tudo se subordina' \u2014 n\xE3o uma autoridade paralela ou superior."},{id:47,capitulo:"XXVIII - Do Batismo",pergunta:"Segundo a Se\xE7\xE3o III, sobre o modo de administra\xE7\xE3o do batismo, a Confiss\xE3o ensina que:",alternativas:["O modo de administra\xE7\xE3o \xE9 indiferente doutrinariamente, mas a Confiss\xE3o exige sempre \xE1gua corrente","A forma de administra\xE7\xE3o deve variar conforme a idade do batizando, exigindo imers\xE3o para adultos","N\xE3o \xE9 necess\xE1rio imergir o candidato na \xE1gua, sendo o batismo devidamente administrado por efus\xE3o ou aspers\xE3o","A efus\xE3o \xE9 a \xFAnica forma v\xE1lida, sendo a aspers\xE3o e a imers\xE3o consideradas inv\xE1lidas","A imers\xE3o total \xE9 a \xFAnica forma v\xE1lida de batismo reconhecida pela Confiss\xE3o, ideia que o texto da Confiss\xE3o, lido em conjunto, n\xE3o sustenta"],respostaCorreta:"N\xE3o \xE9 necess\xE1rio imergir o candidato na \xE1gua, sendo o batismo devidamente administrado por efus\xE3o ou aspers\xE3o",explicacao:"Se\xE7\xE3o III rejeita a exig\xEAncia de imers\xE3o, afirmando expressamente a validade da efus\xE3o ou aspers\xE3o \u2014 posi\xE7\xE3o que difere de tradi\xE7\xF5es que exigem imers\xE3o total."},{id:48,capitulo:"XXXV - Do Amor de Deus e das Miss\xF5es",pergunta:"Segundo a Se\xE7\xE3o IV, visto n\xE3o haver outro caminho de salva\xE7\xE3o sen\xE3o o revelado no Evangelho, qual \xE9 a obriga\xE7\xE3o atribu\xEDda a todos os crentes, e n\xE3o apenas aos ministros ordenados?",alternativas:["Aguardar passivamente a a\xE7\xE3o do Esp\xEDrito, sem qualquer responsabilidade pr\xE1tica atribu\xEDda ao leigo, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","Sustentar as ordenan\xE7as religiosas j\xE1 estabelecidas e contribuir, por ora\xE7\xF5es, ofertas e esfor\xE7os, para a dilata\xE7\xE3o do Reino de Cristo","Administrar os sacramentos sempre que um ministro ordenado estiver ausente da comunidade, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s","Financiar exclusivamente, sem qualquer outra forma de participa\xE7\xE3o pessoal na obra mission\xE1ria, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o","Pregar formalmente em p\xFAblico, fun\xE7\xE3o que a Confiss\xE3o estende a todo crente batizado, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo"],respostaCorreta:"Sustentar as ordenan\xE7as religiosas j\xE1 estabelecidas e contribuir, por ora\xE7\xF5es, ofertas e esfor\xE7os, para a dilata\xE7\xE3o do Reino de Cristo",explicacao:"Se\xE7\xE3o IV: 'Todos os crentes, portanto, t\xEAm por obriga\xE7\xE3o sustentar as ordenan\xE7as religiosas... e contribuir, por meio de suas ora\xE7\xF5es e ofertas e por seus esfor\xE7os, para a dilata\xE7\xE3o do Reino de Cristo'."},{id:49,capitulo:"XXI - Do Culto Religioso e do Domingo",pergunta:"A Se\xE7\xE3o VI afirma que, sob o Evangelho, o culto religioso n\xE3o est\xE1 restrito a um lugar espec\xEDfico, devendo Deus ser adorado 'em esp\xEDrito e verdade'. Qual refer\xEAncia \xE9 citada como apoio a essa parte espec\xEDfica da se\xE7\xE3o?",alternativas:["Lev\xEDtico 1:1-3","N\xFAmeros 28:1-2","Deuteron\xF4mio 12:5-7","\xCAxodo 20:4-6","Jo\xE3o 4:23-24"],respostaCorreta:"Jo\xE3o 4:23-24",explicacao:"A Se\xE7\xE3o VI cita, entre outras, a ideia de adora\xE7\xE3o 'em esp\xEDrito e verdade', associada a Jo\xE3o 4:23-24, sobre a universalidade do lugar de culto sob o Evangelho."},{id:50,capitulo:"XXX - Das Censuras Eclesi\xE1sticas",pergunta:"Segundo a Se\xE7\xE3o III, qual N\xC3O \xE9 apresentada pela Confiss\xE3o como finalidade das censuras eclesi\xE1sticas?",alternativas:["Arrecadar recursos financeiros para a manuten\xE7\xE3o das estruturas eclesi\xE1sticas locais","Evitar a ira de Deus, que poderia cair sobre a Igreja por tolerar ofensores not\xF3rios","Impedir que outros pratiquem ofensas semelhantes \xE0s cometidas","Vindicar a honra de Cristo e a santa profiss\xE3o do Evangelho","Chamar e ganhar para Cristo os irm\xE3os ofensores"],respostaCorreta:"Arrecadar recursos financeiros para a manuten\xE7\xE3o das estruturas eclesi\xE1sticas locais",explicacao:"Se\xE7\xE3o III lista como finalidades: ganhar o ofensor, prevenir ofensas semelhantes, purgar o fermento, vindicar a honra de Cristo e evitar a ira divina \u2014 nenhuma men\xE7\xE3o a finalidade financeira."},{id:51,capitulo:"VIII - De Cristo o Mediador",pergunta:"Segundo a Se\xE7\xE3o II, como a Confiss\xE3o descreve a uni\xE3o entre a natureza divina e a natureza humana em Cristo \u2014 em contraste com o eutiquianismo, que ensinava a fus\xE3o das naturezas em uma s\xF3?",alternativas:["As duas naturezas permaneceram unidas apenas moralmente, sem uni\xE3o real na pessoa de Cristo, divergindo do que a se\xE7\xE3o afirma de modo expl\xEDcito","A natureza divina se retirou temporariamente durante a paix\xE3o, deixando Cristo apenas humano na cruz, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo","As duas naturezas, inteiras e distintas, foram inseparavelmente unidas em uma s\xF3 pessoa, sem convers\xE3o, composi\xE7\xE3o ou confus\xE3o","A natureza humana foi absorvida pela divina no momento da ressurrei\xE7\xE3o, deixando de ser plenamente humana","As duas naturezas se fundiram em uma terceira natureza mista, nem plenamente divina nem plenamente humana"],respostaCorreta:"As duas naturezas, inteiras e distintas, foram inseparavelmente unidas em uma s\xF3 pessoa, sem convers\xE3o, composi\xE7\xE3o ou confus\xE3o",explicacao:"Se\xE7\xE3o II segue a defini\xE7\xE3o de Calced\xF4nia: uni\xE3o hipost\xE1tica sem 'convers\xE3o, composi\xE7\xE3o ou confus\xE3o' \u2014 rejeitando tanto o eutiquianismo (fus\xE3o) quanto o nestorianismo (separa\xE7\xE3o)."},{id:52,capitulo:"XI - Da Justifica\xE7\xE3o",pergunta:"Segundo a Se\xE7\xE3o I, o que exatamente \xE9 imputado ao crente na justifica\xE7\xE3o \u2014 em contraste com uma leitura que toma a pr\xF3pria f\xE9 como a justi\xE7a imputada?",alternativas:["O arrependimento sincero do crente, tomado como equivalente \xE0 obedi\xEAncia que a lei exige","Uma combina\xE7\xE3o entre a f\xE9 exercida e as obras realizadas em estado de gra\xE7a, tal como sustentado por correntes teol\xF3gicas distintas da reformada","A f\xE9 do pr\xF3prio crente, considerada por Deus como um ato de justi\xE7a suficiente diante da lei","A obedi\xEAncia e a satisfa\xE7\xE3o de Cristo, e n\xE3o a f\xE9, o ato de crer ou qualquer outro ato de obedi\xEAncia evang\xE9lica","Uma justi\xE7a infundida gradualmente, que cresce \xE0 medida que o crente pratica boas obras"],respostaCorreta:"A obedi\xEAncia e a satisfa\xE7\xE3o de Cristo, e n\xE3o a f\xE9, o ato de crer ou qualquer outro ato de obedi\xEAncia evang\xE9lica",explicacao:"Se\xE7\xE3o I: Deus n\xE3o imputa 'a pr\xF3pria f\xE9, o ato de crer ou qualquer outro ato de obedi\xEAncia evang\xE9lica, mas... a obedi\xEAncia e a satisfa\xE7\xE3o de Cristo'."},{id:53,capitulo:"V - Da Provid\xEAncia",pergunta:"Segundo a Se\xE7\xE3o III, sobre o uso de meios na provid\xEAncia ordin\xE1ria, a Confiss\xE3o ensina que Deus:",alternativas:["Ordinariamente emprega meios, mas \xE9 livre para operar sem eles, sobre eles ou contra eles, segundo o seu arb\xEDtrio","Est\xE1 sempre limitado a agir por meio de causas naturais j\xE1 estabelecidas na cria\xE7\xE3o, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o","Age exclusivamente por meios extraordin\xE1rios, reservando os ordin\xE1rios apenas \xE0 era apost\xF3lica","Nunca interv\xE9m al\xE9m dos meios ordin\xE1rios, para n\xE3o violar a ordem natural que instituiu, tal como sustentado por correntes teol\xF3gicas distintas da reformada","Abandonou totalmente o uso de meios ap\xF3s a ascens\xE3o de Cristo ao c\xE9u, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo"],respostaCorreta:"Ordinariamente emprega meios, mas \xE9 livre para operar sem eles, sobre eles ou contra eles, segundo o seu arb\xEDtrio",explicacao:"Se\xE7\xE3o III: Deus normalmente emprega meios, mas permanece soberanamente livre para agir sem eles, sobre eles ou contra eles."},{id:54,capitulo:"IX - Do Livre Arb\xEDtrio",pergunta:"Segundo a Se\xE7\xE3o III, o homem ca\xEDdo em estado de pecado, quanto ao bem espiritual que acompanha a salva\xE7\xE3o, est\xE1:",alternativas:["Totalmente incapaz, por seu pr\xF3prio poder, de converter-se ou mesmo de preparar-se para a convers\xE3o","Parcialmente capaz, retendo um resqu\xEDcio de poder espiritual suficiente para iniciar sua pr\xF3pria convers\xE3o","Plenamente capaz de fazer o bem espiritual, embora normalmente escolha n\xE3o faz\xEA-lo","Incapaz apenas de completar a salva\xE7\xE3o, mas capaz de dar o primeiro passo em dire\xE7\xE3o a ela","Capaz de preparar-se moralmente, ainda que a convers\xE3o final dependa s\xF3 de Deus"],respostaCorreta:"Totalmente incapaz, por seu pr\xF3prio poder, de converter-se ou mesmo de preparar-se para a convers\xE3o",explicacao:"Se\xE7\xE3o III nega qualquer capacidade humana aut\xF4noma, mesmo preparat\xF3ria, para o bem espiritual que acompanha a salva\xE7\xE3o \u2014 posi\xE7\xE3o contr\xE1ria ao semipelagianismo."},{id:55,capitulo:"XIX - Da Lei de Deus",pergunta:"A Se\xE7\xE3o II, sobre os dez mandamentos escritos em duas t\xE1buas no monte Sinai, cita qual destas refer\xEAncias?",alternativas:["Rom. 7:12, 22, 25 (citada na Se\xE7\xE3o VI, sobre a lei como regra de vida do crente)","Deut. 10:4","Gal. 3:24 (citada na Se\xE7\xE3o VI, sobre a lei conduzindo o crente a Cristo)","Esdras 9:13-14 (citada na Se\xE7\xE3o VI, sobre as afli\xE7\xF5es merecidas pelo pecado)","Rom. 3:31 (citada na Se\xE7\xE3o V, sobre a lei obrigar para sempre a todos)"],respostaCorreta:"Deut. 10:4",explicacao:"A Se\xE7\xE3o II cita Tiago 1:25 e 2:8, 10; Deut. 5:32 e 10:4; Mat. 22:37-40; as demais op\xE7\xF5es pertencem a outras se\xE7\xF5es do cap\xEDtulo."},{id:56,capitulo:"XXV - Da Igreja",pergunta:"Segundo a Se\xE7\xE3o V, sobre a possibilidade de erro nas igrejas particulares, a Confiss\xE3o ensina que:",alternativas:["A pureza de uma igreja depende exclusivamente da validade formal da sucess\xE3o apost\xF3lica de seus ministros, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","Nenhuma igreja verdadeiramente fundada sobre a Escritura pode jamais degenerar ou cair em erro grave, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o","O erro \xE9 poss\xEDvel apenas em quest\xF5es secund\xE1rias, nunca podendo comprometer a identidade da igreja, tal como sustentado por correntes teol\xF3gicas distintas da reformada","At\xE9 as igrejas mais puras est\xE3o sujeitas \xE0 mistura e ao erro, podendo algumas degenerar a ponto de deixarem de ser igrejas de Cristo","Somente as igrejas que rejeitam formalmente a Confiss\xE3o est\xE3o sujeitas a erro doutrin\xE1rio s\xE9rio, contrariando o sentido direto do texto citado nessa se\xE7\xE3o"],respostaCorreta:"At\xE9 as igrejas mais puras est\xE3o sujeitas \xE0 mistura e ao erro, podendo algumas degenerar a ponto de deixarem de ser igrejas de Cristo",explicacao:"Se\xE7\xE3o V: mesmo 'as igrejas mais puras debaixo do c\xE9u est\xE3o sujeitas \xE0 mistura e ao erro; algumas t\xEAm degenerado ao ponto de n\xE3o serem mais igrejas de Cristo'."},{id:57,capitulo:"I - Da Escritura Sagrada",pergunta:"Segundo a Se\xE7\xE3o I, qual \xE9 a rela\xE7\xE3o exata entre a luz da natureza e a salva\xE7\xE3o?",alternativas:["A luz da natureza equivale em autoridade \xE0 Escritura, servindo como segunda fonte independente de doutrina","A luz da natureza revela genuinamente atributos de Deus e torna os homens inescus\xE1veis, mas n\xE3o basta para o conhecimento salvador","A luz da natureza foi v\xE1lida apenas antes do dil\xFAvio, perdendo toda fun\xE7\xE3o revelat\xF3ria depois dele, tal como sustentado por correntes teol\xF3gicas distintas da reformada","A luz da natureza n\xE3o comunica nenhum conhecimento verdadeiro de Deus, sendo inteiramente anulada pela queda","A luz da natureza \xE9 plenamente suficiente para a salva\xE7\xE3o, dispensando qualquer revela\xE7\xE3o especial escrita"],respostaCorreta:"A luz da natureza revela genuinamente atributos de Deus e torna os homens inescus\xE1veis, mas n\xE3o basta para o conhecimento salvador",explicacao:"Se\xE7\xE3o I: a luz da natureza manifesta a bondade, sabedoria e poder de Deus e torna os homens inescus\xE1veis, mas n\xE3o \xE9 suficiente para dar o conhecimento necess\xE1rio \xE0 salva\xE7\xE3o."},{id:58,capitulo:"VIII - De Cristo o Mediador",pergunta:"A Se\xE7\xE3o IV, sobre a obedi\xEAncia de Cristo \xE0 lei, sua morte, sepultamento e ressurrei\xE7\xE3o ao terceiro dia, cita qual destas refer\xEAncias, tamb\xE9m citada na mesma se\xE7\xE3o?",alternativas:["Isa. 42:1 (citada na Se\xE7\xE3o I, sobre a elei\xE7\xE3o de Cristo como Mediador)","Heb. 7:26 (citada na Se\xE7\xE3o III, sobre a santifica\xE7\xE3o da natureza humana de Cristo)","Jo\xE3o 17:2 (citada na Se\xE7\xE3o V, sobre a satisfa\xE7\xE3o plena \xE0 justi\xE7a do Pai)","Rom. 8:34 (citada na Se\xE7\xE3o IV, mas referente \xE0 intercess\xE3o, n\xE3o \xE0 ressurrei\xE7\xE3o ao terceiro dia)","I Cor. 15:4"],respostaCorreta:"I Cor. 15:4",explicacao:"A Se\xE7\xE3o IV cita I Cor. 15:4 especificamente sobre a ressurrei\xE7\xE3o 'ao terceiro dia'; as demais pertencem a outras partes do cap\xEDtulo ou a outro aspecto da mesma se\xE7\xE3o."},{id:59,capitulo:"XXIV - Do Matrim\xF4nio e do Div\xF3rcio",pergunta:"Segundo a Se\xE7\xE3o VI, para a dissolu\xE7\xE3o leg\xEDtima do matrim\xF4nio, a Confiss\xE3o exige:",alternativas:["A aprova\xE7\xE3o exclusiva do magistrado civil, sem qualquer participa\xE7\xE3o da Igreja no processo","A aprova\xE7\xE3o exclusiva da Igreja local, sem qualquer participa\xE7\xE3o do magistrado civil, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","Um processo p\xFAblico e regular, n\xE3o podendo o caso ser decidido pelo mero arb\xEDtrio e discri\xE7\xE3o das pr\xF3prias partes","Um per\xEDodo m\xEDnimo de separa\xE7\xE3o informal, ap\xF3s o qual o div\xF3rcio se torna autom\xE1tico, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o","Apenas o consentimento m\xFAtuo das partes, formalizado por escrito perante testemunhas, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o"],respostaCorreta:"Um processo p\xFAblico e regular, n\xE3o podendo o caso ser decidido pelo mero arb\xEDtrio e discri\xE7\xE3o das pr\xF3prias partes",explicacao:"Se\xE7\xE3o VI exige processo p\xFAblico e regular, vedando que as pr\xF3prias partes decidam autonomamente o caso."},{id:60,capitulo:"XXXIV - Do Esp\xEDrito Santo",pergunta:"Segundo a Se\xE7\xE3o III, qual \xE9 o papel do Esp\xEDrito Santo na aplica\xE7\xE3o da reden\xE7\xE3o, em contraste com uma leitura sinergista que divide igualmente essa aplica\xE7\xE3o entre Deus e o homem?",alternativas:["Limita-se a confirmar externamente, pelos sacramentos, uma f\xE9 j\xE1 gerada por esfor\xE7o pr\xF3prio do crente","\xC9 o \xFAnico agente eficaz na aplica\xE7\xE3o da reden\xE7\xE3o, convencendo, regenerando e habilitando os homens a abra\xE7ar a Cristo pela f\xE9","Atua apenas de modo auxiliar, fortalecendo uma decis\xE3o que a vontade humana j\xE1 tomou por si mesma, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","\xC9 um entre v\xE1rios agentes igualmente respons\xE1veis, cooperando com a vontade humana em condi\xE7\xF5es de igualdade","Age somente sobre os ministros ordenados, transmitindo por eles a efic\xE1cia da reden\xE7\xE3o aos demais, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o"],respostaCorreta:"\xC9 o \xFAnico agente eficaz na aplica\xE7\xE3o da reden\xE7\xE3o, convencendo, regenerando e habilitando os homens a abra\xE7ar a Cristo pela f\xE9",explicacao:"Se\xE7\xE3o III: o Esp\xEDrito Santo '\xE9 o \xFAnico agente eficaz na aplica\xE7\xE3o da reden\xE7\xE3o' \u2014 posi\xE7\xE3o monergista quanto \xE0 aplica\xE7\xE3o da salva\xE7\xE3o."},{id:61,capitulo:"XXXIII - Do Ju\xEDzo Final",pergunta:"Segundo a Se\xE7\xE3o III, por que Deus quer que o dia do ju\xEDzo permane\xE7a desconhecido dos homens, apesar de quererem que estejam convictos de que ele ocorrer\xE1?",alternativas:["Para que os homens se despojem de toda confian\xE7a carnal, sejam sempre vigilantes e estejam prontos, n\xE3o sabendo a hora","Para poder julgar em segredo os que tentarem calcular ou prever a data exata do evento, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","Porque o ju\xEDzo final j\xE1 ocorreu de modo espiritual e invis\xEDvel na hist\xF3ria da Igreja, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional","Para que apenas os eleitos, por revela\xE7\xE3o especial, possam antecipar corretamente a data, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","Porque o pr\xF3prio Deus ainda n\xE3o determinou definitivamente quando esse dia ocorrer\xE1, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s"],respostaCorreta:"Para que os homens se despojem de toda confian\xE7a carnal, sejam sempre vigilantes e estejam prontos, n\xE3o sabendo a hora",explicacao:"Se\xE7\xE3o III: o desconhecimento da data serve para que os homens 'se despojem de toda confian\xE7a carnal, sejam sempre vigilantes... e estejam prontos'."},{id:62,capitulo:"XVI - Das Boas Obras",pergunta:"Segundo a Se\xE7\xE3o III, o poder de praticar boas obras no crente regenerado prov\xE9m:",alternativas:["Inteiramente do Esp\xEDrito de Cristo, exigindo uma influ\xEAncia positiva cont\xEDnua do Esp\xEDrito al\xE9m da gra\xE7a j\xE1 recebida","Da pr\xF3pria vontade humana renovada, que passa a agir de modo aut\xF4nomo em rela\xE7\xE3o \xE0 gra\xE7a, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional","Da disciplina eclesi\xE1stica, que capacita moralmente o crente por meio dos sacramentos, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o","De um esfor\xE7o moral independente, complementado apenas ocasionalmente pela gra\xE7a divina, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","De um m\xE9rito acumulado progressivamente, que dispensa nova assist\xEAncia divina ap\xF3s certo ponto"],respostaCorreta:"Inteiramente do Esp\xEDrito de Cristo, exigindo uma influ\xEAncia positiva cont\xEDnua do Esp\xEDrito al\xE9m da gra\xE7a j\xE1 recebida",explicacao:"Se\xE7\xE3o III: o poder de fazer boas obras 'n\xE3o \xE9 de modo algum dos pr\xF3prios fi\xE9is, mas prov\xE9m inteiramente do Esp\xEDrito de Cristo', exigindo influ\xEAncia cont\xEDnua al\xE9m da gra\xE7a j\xE1 recebida."},{id:63,capitulo:"XXIII - Do Magistrado Civil",pergunta:"Segundo a Se\xE7\xE3o IV, a incredulidade ou a indiferen\xE7a religiosa de um magistrado civil:",alternativas:["Dispensa exclusivamente os eclesi\xE1sticos da obedi\xEAncia, embora o restante do povo permane\xE7a obrigado","Anula automaticamente sua autoridade leg\xEDtima, dispensando o povo de qualquer obedi\xEAncia civil","Torna sua autoridade v\xE1lida apenas em assuntos estritamente civis, nunca em qualquer outro \xE2mbito","Obriga o povo a resistir ativamente at\xE9 que um magistrado professamente crist\xE3o assuma o cargo","N\xE3o anula sua justa e legal autoridade, nem dispensa o povo, incluindo os eclesi\xE1sticos, da obedi\xEAncia devida"],respostaCorreta:"N\xE3o anula sua justa e legal autoridade, nem dispensa o povo, incluindo os eclesi\xE1sticos, da obedi\xEAncia devida",explicacao:"Se\xE7\xE3o IV: 'Incredulidade ou indiferen\xE7a de religi\xE3o n\xE3o anula a justa e legal autoridade do magistrado, nem absolve o povo da obedi\xEAncia que lhe deve'."},{id:64,capitulo:"XV - Do Arrependimento para a Vida",pergunta:"Segundo a Se\xE7\xE3o III, qual \xE9 a rela\xE7\xE3o exata entre o arrependimento e o perd\xE3o dos pecados \u2014 em contraste com uma leitura que trata o arrependimento como satisfa\xE7\xE3o penitencial?",alternativas:["O arrependimento \xE9 dispens\xE1vel, bastando a f\xE9 inicial professada no momento da convers\xE3o, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional","O arrependimento \xE9 necess\xE1rio para que o pecador espere o perd\xE3o, mas n\xE3o \xE9 ele mesmo uma satisfa\xE7\xE3o pelo pecado, nem a causa do perd\xE3o","O arrependimento \xE9 a causa direta e suficiente do perd\xE3o, independente da obra de Cristo, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo","O arrependimento deve ser mediado por um sacerdote para ter qualquer efic\xE1cia diante de Deus, tal como sustentado por correntes teol\xF3gicas distintas da reformada","O arrependimento constitui uma satisfa\xE7\xE3o parcial pelo pecado, complementando a obra de Cristo, contrariando o sentido direto do texto citado nessa se\xE7\xE3o"],respostaCorreta:"O arrependimento \xE9 necess\xE1rio para que o pecador espere o perd\xE3o, mas n\xE3o \xE9 ele mesmo uma satisfa\xE7\xE3o pelo pecado, nem a causa do perd\xE3o",explicacao:"Se\xE7\xE3o III distingue claramente: o perd\xE3o \xE9 ato da livre gra\xE7a de Deus em Cristo, mas o arrependimento \xE9, ainda assim, necess\xE1rio aos pecadores."},{id:65,capitulo:"VII - Do Pacto de Deus com o Homem",pergunta:"Segundo a Se\xE7\xE3o II, o pacto de obras feito com Ad\xE3o prometia vida sob qual condi\xE7\xE3o?",alternativas:["Observ\xE2ncia exclusivamente do preceito de n\xE3o comer da \xE1rvore proibida, sem exig\xEAncia mais ampla","F\xE9 sincera, ainda que acompanhada de obedi\xEAncia imperfeita","Obedi\xEAncia parcial, suficiente desde que a inten\xE7\xE3o fosse reta","Perfeita obedi\xEAncia pessoal","Arrependimento cont\xEDnuo diante de qualquer transgress\xE3o cometida"],respostaCorreta:"Perfeita obedi\xEAncia pessoal",explicacao:"Se\xE7\xE3o II: 'foi a vida prometida a Ad\xE3o... sob a condi\xE7\xE3o de perfeita obedi\xEAncia pessoal'."},{id:66,capitulo:"III - Dos Eternos Decretos de Deus",pergunta:"O debate teol\xF3gico entre supralapsarianismo e infralapsarianismo trata da ordem l\xF3gica dos decretos divinos. Como o texto do Cap\xEDtulo III se posiciona explicitamente nesse debate?",alternativas:["O texto condena formalmente o supralapsarianismo como incompat\xEDvel com a soberania divina, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o","O texto declara explicitamente a ordem infralapsariana, afirmando que o decreto de elei\xE7\xE3o pressup\xF5e logicamente a queda j\xE1 decretada","O texto resolve o debate citando Romanos 9 como prova conclusiva a favor de uma das duas ordens, divergindo do que a se\xE7\xE3o afirma de modo expl\xEDcito","O texto declara explicitamente a ordem supralapsariana, afirmando que o decreto de elei\xE7\xE3o precede logicamente o decreto da queda, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o","O texto n\xE3o adota terminologia t\xE9cnica de nenhum dos dois esquemas, permitindo historicamente leituras supra e infralapsarianas dentro da tradi\xE7\xE3o reformada"],respostaCorreta:"O texto n\xE3o adota terminologia t\xE9cnica de nenhum dos dois esquemas, permitindo historicamente leituras supra e infralapsarianas dentro da tradi\xE7\xE3o reformada",explicacao:"O Cap\xEDtulo III \xE9 redigido de modo deliberadamente amplo quanto \xE0 ordem l\xF3gica dos decretos, sem comprometer-se formalmente com supra ou infralapsarianismo \u2014 por isso ambas as posi\xE7\xF5es convivem historicamente dentro do presbiterianismo confessional."},{id:67,capitulo:"XIV - Da F\xE9 Salvadora",pergunta:"Segundo a Se\xE7\xE3o III, a f\xE9 salvadora, quanto ao seu grau ao longo da vida do crente:",alternativas:["Permanece est\xE1tica, sem qualquer rela\xE7\xE3o com as prova\xE7\xF5es ou tenta\xE7\xF5es enfrentadas pelo crente","Uma vez enfraquecida por assaltos e d\xFAvidas, n\xE3o pode mais ser restaurada nesta vida","Pode ser fraca ou forte, sendo muitas vezes assaltada e enfraquecida, mas sempre alcan\xE7ando a vit\xF3ria final","\xC9 anulada por qualquer d\xFAvida moment\xE2nea, exigindo nova convers\xE3o para ser restabelecida","\xC9 concedida sempre em grau m\xE1ximo desde a convers\xE3o, n\xE3o admitindo varia\xE7\xE3o posterior"],respostaCorreta:"Pode ser fraca ou forte, sendo muitas vezes assaltada e enfraquecida, mas sempre alcan\xE7ando a vit\xF3ria final",explicacao:"Se\xE7\xE3o III: a f\xE9 '\xE9 de diferentes graus... pode ser muitas vezes e de muitos modos assaltada e enfraquecida, mas sempre alcan\xE7a a vit\xF3ria'."},{id:68,capitulo:"XIII - Da Santifica\xE7\xE3o",pergunta:"Segundo a Se\xE7\xE3o II, a santifica\xE7\xE3o nesta vida \xE9 descrita como:",alternativas:["Presente no homem todo, mas imperfeita, restando uma guerra cont\xEDnua e irreconcili\xE1vel entre carne e esp\xEDrito","Progressiva at\xE9 alcan\xE7ar impecabilidade plena ainda nesta vida, para os crentes mais maduros","Um processo reservado exclusivamente ao momento da glorifica\xE7\xE3o, n\xE3o iniciado nesta vida","Limitada \xE0 vida interior, sem qualquer efeito pr\xE1tico sobre o comportamento exterior do crente","Completa no momento da regenera\xE7\xE3o, restando apenas o combate contra tenta\xE7\xF5es puramente externas"],respostaCorreta:"Presente no homem todo, mas imperfeita, restando uma guerra cont\xEDnua e irreconcili\xE1vel entre carne e esp\xEDrito",explicacao:"Se\xE7\xE3o II: a santifica\xE7\xE3o \xE9 'no homem todo, por\xE9m imperfeita nesta vida... uma guerra cont\xEDnua e irreconcili\xE1vel'."},{id:69,capitulo:"XIX - Da Lei de Deus",pergunta:"Segundo a Se\xE7\xE3o VI, os verdadeiros crentes, embora n\xE3o estejam sob a lei como pacto de obras para serem justificados ou condenados por ela, ainda assim:",alternativas:["Ficam inteiramente dispensados de qualquer rela\xE7\xE3o com a lei moral, por j\xE1 estarem sob a gra\xE7a","Devem observar a lei apenas como conselho opcional, sem qualquer fun\xE7\xE3o normativa em sua vida","Permanecem sob a mesma condena\xE7\xE3o potencial da lei, caso n\xE3o a cumpram integralmente cada dia","S\xE3o instru\xEDdos a evitar qualquer uso da lei, sob risco de recair no legalismo condenado por Paulo","Recebem da lei grande proveito como regra de vida, que revela o pecado, humilha e conduz a maior aprecia\xE7\xE3o de Cristo"],respostaCorreta:"Recebem da lei grande proveito como regra de vida, que revela o pecado, humilha e conduz a maior aprecia\xE7\xE3o de Cristo",explicacao:"Se\xE7\xE3o VI descreve o chamado 'terceiro uso da lei': ainda n\xE3o como pacto de obras, a lei orienta, humilha e conduz o crente a Cristo \u2014 distinta de uma leitura que dispensa totalmente a lei da vida do crente."},{id:70,capitulo:"XXIII - Do Magistrado Civil",pergunta:"A Se\xE7\xE3o I, sobre Deus constituir magistrados civis armados com o poder da espada, cita qual destas refer\xEAncias?",alternativas:["I Ped. 2:13-16 (citada na Se\xE7\xE3o IV, sobre honrar e obedecer aos magistrados)","Rom. 13:1-4","Mat. 16:19 (citada na Se\xE7\xE3o III, sobre o poder das chaves n\xE3o pertencer ao magistrado)","Prov. 8:15-16 (citada na Se\xE7\xE3o II, sobre ser l\xEDcito aos crist\xE3os exercer a magistratura)","At. 25:10-11 (citada na Se\xE7\xE3o IV, sobre o papa n\xE3o ter jurisdi\xE7\xE3o sobre os magistrados)"],respostaCorreta:"Rom. 13:1-4",explicacao:"A Se\xE7\xE3o I cita Rom. 13:1-4 e I Ped. 2:13-14, referentes \xE0 institui\xE7\xE3o divina do magistrado civil; as demais pertencem a outras se\xE7\xF5es do cap\xEDtulo."},{id:71,capitulo:"XX - Da Liberdade Crist\xE3 e da Liberdade de Consci\xEAncia",pergunta:"Segundo a Se\xE7\xE3o IV, aqueles que, sob pretexto de liberdade crist\xE3, se op\xF5em a qualquer poder leg\xEDtimo civil ou religioso:",alternativas:["Resistem \xE0 ordenan\xE7a de Deus e podem ser processados e visitados com as censuras eclesi\xE1sticas, conforme o caso","S\xE3o protegidos pela Confiss\xE3o desde que aleguem motiva\xE7\xE3o estritamente religiosa para sua oposi\xE7\xE3o","Ficam sujeitos apenas \xE0 disciplina civil, estando isentos de qualquer censura eclesi\xE1stica","Devem ser tolerados sempre, pois a liberdade crist\xE3 prevalece sobre qualquer autoridade institu\xEDda","Exercem legitimamente seu direito de consci\xEAncia, imunes a qualquer censura civil ou eclesi\xE1stica"],respostaCorreta:"Resistem \xE0 ordenan\xE7a de Deus e podem ser processados e visitados com as censuras eclesi\xE1sticas, conforme o caso",explicacao:"Se\xE7\xE3o IV: tal oposi\xE7\xE3o 'resiste \xE0 ordenan\xE7a de Deus' e pode, de justi\xE7a, ser processada e visitada com censuras eclesi\xE1sticas."},{id:72,capitulo:"VI - Da Queda do Homem, do Pecado e do seu Castigo",pergunta:"Segundo a Se\xE7\xE3o V, a corrup\xE7\xE3o da natureza que persiste nos regenerados durante esta vida:",alternativas:["\xC9 inteiramente removida no momento do batismo, restando apenas tenta\xE7\xF5es externas, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","Torna-se moralmente neutra, sendo culp\xE1vel apenas quando reincide reiteradamente, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional","S\xF3 volta a ser pecado se resultar em um ato exterior deliberado e consciente, divergindo do que a se\xE7\xE3o afirma de modo expl\xEDcito","\xC9, tanto ela quanto os seus impulsos, real e propriamente pecado, ainda que perdoada e mortificada por Cristo","Deixa de ser propriamente pecado assim que a pessoa \xE9 regenerada, tornando-se mera fraqueza moral"],respostaCorreta:"\xC9, tanto ela quanto os seus impulsos, real e propriamente pecado, ainda que perdoada e mortificada por Cristo",explicacao:"Se\xE7\xE3o V: mesmo perdoada e mortificada, a corrup\xE7\xE3o remanescente e seus impulsos 's\xE3o real e propriamente pecado'."},{id:73,capitulo:"XI - Da Justifica\xE7\xE3o",pergunta:"Segundo a Se\xE7\xE3o II, qual \xE9 a rela\xE7\xE3o entre a f\xE9 justificadora e as boas obras, segundo a f\xF3rmula da Confiss\xE3o \u2014 em contraste com uma leitura antinomista?",alternativas:["A f\xE9 e as boas obras s\xE3o igualmente instrumentos de justifica\xE7\xE3o, cooperando lado a lado, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o","As boas obras precedem a f\xE9, preparando o cora\xE7\xE3o para receb\xEA-la legitimamente, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","A f\xE9 justificadora dispensa qualquer fruto vis\xEDvel, manifestando-se apenas internamente, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s","A f\xE9 nunca est\xE1 sozinha na pessoa justificada, mas sempre \xE9 acompanhada de outras gra\xE7as salvadoras e obra por amor","A f\xE9 justificadora \xE9 suficiente por si mesma, sendo as boas obras inteiramente irrelevantes ap\xF3s a justifica\xE7\xE3o"],respostaCorreta:"A f\xE9 nunca est\xE1 sozinha na pessoa justificada, mas sempre \xE9 acompanhada de outras gra\xE7as salvadoras e obra por amor",explicacao:"Se\xE7\xE3o II: a f\xE9 'n\xE3o est\xE1 sozinha na pessoa justificada... n\xE3o \xE9 uma f\xE9 morta, mas obra por amor' \u2014 contra o antinomismo, mas sem tornar as obras instrumento de justifica\xE7\xE3o."},{id:74,capitulo:"XVII - Da Perseveran\xE7a dos Santos",pergunta:"A Se\xE7\xE3o I, sobre os santos n\xE3o poderem decair do estado de gra\xE7a nem total nem finalmente, cita qual destas refer\xEAncias?",alternativas:["Jo\xE3o 10:28-29","Rom. 8:33-34, 38-39 (citada na Se\xE7\xE3o II, sobre nada poder separar do amor de Cristo)","I Jo\xE3o 2:19 (citada na Se\xE7\xE3o II, sobre os que sa\xEDram por n\xE3o serem dos nossos)","II Tim. 2:19 (citada na Se\xE7\xE3o II, sobre o fundamento e o selo do Senhor)","Jer. 31:3 (citada na Se\xE7\xE3o II, sobre o amor imut\xE1vel de Deus Pai)"],respostaCorreta:"Jo\xE3o 10:28-29",explicacao:"A Se\xE7\xE3o I cita Fil. 1:6, Jo\xE3o 10:28-29 e I Ped. 1:5, 9; as demais alternativas pertencem \xE0 Se\xE7\xE3o II do mesmo cap\xEDtulo."},{id:75,capitulo:"IV - Da Cria\xE7\xE3o",pergunta:"A express\xE3o da Se\xE7\xE3o I, 'no espa\xE7o de seis dias', tem sido historicamente central em debates confessionais reformados. Qual leitura essa express\xE3o tende a apoiar, segundo boa parte dos int\xE9rpretes confessionalistas mais estritos?",alternativas:["Um \xFAnico instante atemporal de cria\xE7\xE3o, sendo os 'seis dias' apenas um recurso liter\xE1rio posterior","Seis semanas simb\xF3licas, cada uma representando uma \xE9poca da hist\xF3ria da Igreja","Um relato m\xEDtico sem qualquer pretens\xE3o cronol\xF3gica, an\xE1logo \xE0s cosmogonias do antigo Oriente Pr\xF3ximo","Seis per\xEDodos geol\xF3gicos de dura\xE7\xE3o indeterminada, compat\xEDveis com a cronologia da geologia moderna","Seis dias literais e sucessivos de cria\xE7\xE3o, em oposi\xE7\xE3o a leituras de dias-eras ou puramente aleg\xF3ricas"],respostaCorreta:"Seis dias literais e sucessivos de cria\xE7\xE3o, em oposi\xE7\xE3o a leituras de dias-eras ou puramente aleg\xF3ricas",explicacao:"A frase 'no espa\xE7o de seis dias' \xE9 historicamente lida por confessionalistas mais estritos como apoio \xE0 cria\xE7\xE3o em seis dias literais, embora o tema tenha gerado debate dentro do presbiterianismo conservador."},{id:76,capitulo:"XXVIII - Do Batismo",pergunta:"Segundo a Se\xE7\xE3o IV, al\xE9m dos que professam f\xE9 pessoal em Cristo, quem mais deve ser batizado, segundo a Confiss\xE3o \u2014 em contraste com a posi\xE7\xE3o credobatista?",alternativas:["Nenhuma crian\xE7a, devendo o batismo aguardar sempre a profiss\xE3o pessoal e consciente de f\xE9","Qualquer crian\xE7a apresentada por padrinhos, independentemente da f\xE9 dos pais biol\xF3gicos","Somente crian\xE7as cujos dois pais sejam membros comungantes plenos da mesma congrega\xE7\xE3o local","Apenas adultos que tenham completado um per\xEDodo formal de instru\xE7\xE3o catequ\xE9tica pr\xE9via","Os filhos de pais crentes, ainda que apenas um dos pais seja crente"],respostaCorreta:"Os filhos de pais crentes, ainda que apenas um dos pais seja crente",explicacao:"Se\xE7\xE3o IV afirma o batismo infantil de filhos de ao menos um pai crente \u2014 posi\xE7\xE3o que se distingue da exig\xEAncia credobatista de profiss\xE3o pessoal de f\xE9 como pr\xE9-requisito ao batismo."},{id:77,capitulo:"V - Da Provid\xEAncia",pergunta:"Segundo a Se\xE7\xE3o IV, a provid\xEAncia de Deus sobre a queda e os pecados dos anjos e dos homens ocorre:",alternativas:["N\xE3o por mera permiss\xE3o passiva, mas por uma permiss\xE3o que s\xE1bia e poderosamente limita, regula e governa o mal para fins santos, sem que Deus seja o autor do pecado","Por mera permiss\xE3o passiva, sem qualquer governo, limite ou dire\xE7\xE3o divina sobre o que ocorre, ideia que o texto da Confiss\xE3o, lido em conjunto, n\xE3o sustenta","Por retirada total da provid\xEAncia nesses casos, agindo o mal fora do controle soberano de Deus, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","Por decreto direto e eficiente do mal, do mesmo modo como Deus decreta e produz o bem, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","Por coopera\xE7\xE3o sim\xE9trica entre Deus e Satan\xE1s na produ\xE7\xE3o do mal moral, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o"],respostaCorreta:"N\xE3o por mera permiss\xE3o passiva, mas por uma permiss\xE3o que s\xE1bia e poderosamente limita, regula e governa o mal para fins santos, sem que Deus seja o autor do pecado",explicacao:"Se\xE7\xE3o IV distingue cuidadosamente entre governo soberano do mal e autoria do mal: Deus governa e limita, mas a pecaminosidade procede s\xF3 da criatura."},{id:78,capitulo:"IV - Da Cria\xE7\xE3o",pergunta:"Segundo a Se\xE7\xE3o II, antes da queda, a vontade de Ad\xE3o e Eva em rela\xE7\xE3o ao pecado era:",alternativas:["Imutavelmente fixada no bem, sem qualquer possibilidade real de pecar","Neutra e sem capacidade moral alguma, adquirida somente ap\xF3s comerem do fruto","J\xE1 inclinada ao mal, sendo a queda apenas a manifesta\xE7\xE3o de uma tend\xEAncia preexistente","Mut\xE1vel \u2014 tinham poder de obedecer, mas tamb\xE9m a possibilidade real de transgredir","Determinada exclusivamente por Satan\xE1s, sem responsabilidade moral pr\xF3pria"],respostaCorreta:"Mut\xE1vel \u2014 tinham poder de obedecer, mas tamb\xE9m a possibilidade real de transgredir",explicacao:"Se\xE7\xE3o II: tinham 'o poder de cumpri-la, mas com a possibilidade de transgredi-la, sendo deixados \xE0 liberdade da sua pr\xF3pria vontade, que era mut\xE1vel'."},{id:79,capitulo:"XXXI - Dos S\xEDnodos e Conc\xEDlios",pergunta:"Segundo a Se\xE7\xE3o IV, os s\xEDnodos e conc\xEDlios n\xE3o devem discutir ou determinar:",alternativas:["Qualquer mat\xE9ria disciplinar interna, que deve ser deixada inteiramente \xE0s congrega\xE7\xF5es locais, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional","Quest\xF5es doutrin\xE1rias j\xE1 tratadas em conc\xEDlios anteriores, ainda que de forma insatisfat\xF3ria, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","Assuntos relacionados \xE0 ordena\xE7\xE3o de ministros, reservados exclusivamente aos presbit\xE9rios locais, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s","Nenhuma quest\xE3o de f\xE9, devendo restringir-se exclusivamente a assuntos de organiza\xE7\xE3o administrativa, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo","Coisa alguma que n\xE3o seja eclesi\xE1stica, nem imiscuir-se nos neg\xF3cios civis do Estado, salvo por humilde peti\xE7\xE3o em casos extraordin\xE1rios"],respostaCorreta:"Coisa alguma que n\xE3o seja eclesi\xE1stica, nem imiscuir-se nos neg\xF3cios civis do Estado, salvo por humilde peti\xE7\xE3o em casos extraordin\xE1rios",explicacao:"Se\xE7\xE3o IV: s\xEDnodos n\xE3o devem tratar de assuntos n\xE3o eclesi\xE1sticos nem interferir nos neg\xF3cios civis, exceto por humilde peti\xE7\xE3o em casos extraordin\xE1rios ou a convite do magistrado."},{id:80,capitulo:"XVIII - Da Certeza da Gra\xE7a e da Salva\xE7\xE3o",pergunta:"Segundo a Se\xE7\xE3o III, a seguran\xE7a infal\xEDvel de salva\xE7\xE3o pertence \xE0 ess\xEAncia da f\xE9 de tal modo que todo crente verdadeiro a possui desde o in\xEDcio da sua f\xE9?",alternativas:["N\xE3o; a seguran\xE7a infal\xEDvel \xE9, na verdade, inating\xEDvel nesta vida para qualquer crente, por mais maduro que seja, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o","N\xE3o \xE9 tratado nesta se\xE7\xE3o, que se ocupa apenas da natureza da f\xE9, n\xE3o da certeza, tal como sustentado por correntes teol\xF3gicas distintas da reformada","Sim, mas apenas para os que recebem uma revela\xE7\xE3o extraordin\xE1ria confirmando sua elei\xE7\xE3o, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","Sim; a f\xE9 salvadora inclui necessariamente, desde o primeiro momento, a certeza plena e consciente da salva\xE7\xE3o, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","N\xE3o; um crente verdadeiro pode esperar muito e lutar com dificuldades antes de alcan\xE7\xE1-la, ainda que ela seja acess\xEDvel pelo uso dos meios ordin\xE1rios"],respostaCorreta:"N\xE3o; um crente verdadeiro pode esperar muito e lutar com dificuldades antes de alcan\xE7\xE1-la, ainda que ela seja acess\xEDvel pelo uso dos meios ordin\xE1rios",explicacao:"Se\xE7\xE3o III: a seguran\xE7a infal\xEDvel 'n\xE3o pertence de tal modo \xE0 ess\xEAncia da f\xE9, que um verdadeiro crente, antes de possu\xED-la, n\xE3o tenha de esperar muito e lutar com muitas dificuldades'."},{id:81,capitulo:"XIII - Da Santifica\xE7\xE3o",pergunta:"Segundo a Se\xE7\xE3o III, quem prevalece, ao final, na guerra entre a carne e o esp\xEDrito no crente?",alternativas:["A parte regenerada do homem novo, pelo cont\xEDnuo socorro do Esp\xEDrito de Cristo, embora as corrup\xE7\xF5es remanescentes possam prevalecer por algum tempo","A carne e o esp\xEDrito se equilibram de forma est\xE1vel, sem que a santifica\xE7\xE3o avance com o tempo, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s","Nenhuma das partes prevalece definitivamente; a guerra permanece em empate perp\xE9tuo nesta vida, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o","A vit\xF3ria depende inteiramente do esfor\xE7o moral do crente, sem rela\xE7\xE3o direta com a obra do Esp\xEDrito, divergindo do que a se\xE7\xE3o afirma de modo expl\xEDcito","A carne prevalece de modo permanente, sendo a vit\xF3ria do esp\xEDrito reservada apenas para depois da morte, ideia que o texto da Confiss\xE3o, lido em conjunto, n\xE3o sustenta"],respostaCorreta:"A parte regenerada do homem novo, pelo cont\xEDnuo socorro do Esp\xEDrito de Cristo, embora as corrup\xE7\xF5es remanescentes possam prevalecer por algum tempo",explicacao:"Se\xE7\xE3o III: 'a parte regenerada do homem novo vence, e assim os santos crescem em gra\xE7a', ainda que as corrup\xE7\xF5es remanescentes prevale\xE7am por algum tempo."},{id:82,capitulo:"III - Dos Eternos Decretos de Deus",pergunta:"A Se\xE7\xE3o VI do Cap\xEDtulo III, sobre os meios que Deus preordenou para conduzir os eleitos \xE0 gl\xF3ria (queda, reden\xE7\xE3o por Cristo, voca\xE7\xE3o eficaz e santifica\xE7\xE3o), cita qual destas refer\xEAncias, tamb\xE9m citada na mesma se\xE7\xE3o?",alternativas:["Rom. 9:22-23 (citada na Se\xE7\xE3o III, sobre a predestina\xE7\xE3o de homens e anjos)","At. 15:18 (citada na Se\xE7\xE3o II, sobre Deus n\xE3o decretar por presci\xEAncia)","Isa. 45:6-7 (citada na Se\xE7\xE3o I, sobre o decreto n\xE3o ser autor do pecado)","I Pedro 1:2","Deut. 29:29 (citada na Se\xE7\xE3o VIII, sobre a prud\xEAncia ao tratar da predestina\xE7\xE3o)"],respostaCorreta:"I Pedro 1:2",explicacao:"A Se\xE7\xE3o VI cita I Pedro 1:2 entre suas refer\xEAncias; as demais op\xE7\xF5es pertencem a outras se\xE7\xF5es do mesmo cap\xEDtulo, o que exige aten\xE7\xE3o \xE0 se\xE7\xE3o exata."},{id:83,capitulo:"IX - Do Livre Arb\xEDtrio",pergunta:"Segundo a Se\xE7\xE3o IV, quando Deus converte um pecador, este passa a:",alternativas:["Agir sempre movido apenas pelo bem, sem jamais desejar o que \xE9 mau em qualquer medida, o que esvaziaria o sentido pastoral atribu\xEDdo \xE0 se\xE7\xE3o","Perder toda capacidade de pecar, tornando-se moralmente impec\xE1vel a partir da convers\xE3o, ainda que essa leitura seja defendida por outras tradi\xE7\xF5es crist\xE3s","Fazer o bem de modo perfeito e imut\xE1vel j\xE1 nesta vida, sem qualquer resqu\xEDcio de corrup\xE7\xE3o, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","Alcan\xE7ar liberdade plena e definitiva apenas depois de completar um processo formal de santifica\xE7\xE3o, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo","Querer e fazer com liberdade o que \xE9 espiritualmente bom, ainda que, por causa da corrup\xE7\xE3o remanescente, n\xE3o o fa\xE7a perfeitamente"],respostaCorreta:"Querer e fazer com liberdade o que \xE9 espiritualmente bom, ainda que, por causa da corrup\xE7\xE3o remanescente, n\xE3o o fa\xE7a perfeitamente",explicacao:"Se\xE7\xE3o IV: a gra\xE7a habilita para o bem 'com toda a liberdade', mas 'por causa da corrup\xE7\xE3o, ainda nele existente, o pecador n\xE3o faz o bem perfeitamente'."},{id:84,capitulo:"XXII - Dos Juramentos Legais e dos Votos",pergunta:"Segundo a Se\xE7\xE3o VII, como a Confiss\xE3o avalia os votos mon\xE1sticos de celibato perp\xE9tuo, pobreza volunt\xE1ria e obedi\xEAncia regular?",alternativas:["Como neutras, aceit\xE1veis desde que a pessoa as tenha assumido livremente e sem coa\xE7\xE3o","Como pr\xE1ticas leg\xEDtimas, embora reservadas apenas a uma minoria de voca\xE7\xE3o especial","Como recomend\xE1veis, embora n\xE3o obrigat\xF3rias para a generalidade dos crist\xE3os","Como la\xE7os supersticiosos e in\xEDquos, e n\xE3o como graus de maior perfei\xE7\xE3o espiritual","Como equivalentes espirituais ao batismo, quando feitos com sinceridade de cora\xE7\xE3o"],respostaCorreta:"Como la\xE7os supersticiosos e in\xEDquos, e n\xE3o como graus de maior perfei\xE7\xE3o espiritual",explicacao:"Se\xE7\xE3o VII: tais votos 'n\xE3o passam de la\xE7os supersticiosos e in\xEDquos com os quais nenhum crist\xE3o deve embara\xE7ar-se'."},{id:85,capitulo:"XV - Do Arrependimento para a Vida",pergunta:"Segundo a Se\xE7\xE3o IV, sobre a gravidade relativa dos pecados e o alcance do perd\xE3o, a Confiss\xE3o ensina que:",alternativas:["Existem pecados veniais, que n\xE3o separam da gra\xE7a, e pecados mortais, que exigem penit\xEAncia formal","A gravidade do pecado \xE9 irrelevante, pois todo pecado recebe o mesmo grau de puni\xE7\xE3o eterna, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","Todo pecado, por menor que seja, \xE9 automaticamente perdoado, independentemente de arrependimento, o que n\xE3o corresponde \xE0 formula\xE7\xE3o exata usada pela Confiss\xE3o","Certos pecados s\xE3o categoricamente imperdo\xE1veis, mesmo diante de arrependimento sincero e genu\xEDno, posi\xE7\xE3o incompat\xEDvel com o restante do texto confessional","N\xE3o h\xE1 pecado t\xE3o pequeno que n\xE3o mere\xE7a condena\xE7\xE3o, nem pecado t\xE3o grande que condene os que verdadeiramente se arrependem"],respostaCorreta:"N\xE3o h\xE1 pecado t\xE3o pequeno que n\xE3o mere\xE7a condena\xE7\xE3o, nem pecado t\xE3o grande que condene os que verdadeiramente se arrependem",explicacao:"Se\xE7\xE3o IV: nenhum pecado \xE9 pequeno demais para merecer condena\xE7\xE3o, nem grande demais para impedir o perd\xE3o ao verdadeiramente arrependido \u2014 distinta da distin\xE7\xE3o cat\xF3lica entre pecados veniais e mortais."},{id:86,capitulo:"XIX - Da Lei de Deus",pergunta:"Segundo a Se\xE7\xE3o III, as leis cerimoniais dadas a Israel, sob a Confiss\xE3o:",alternativas:["Permanecem parcialmente em vigor, sobretudo quanto \xE0s leis alimentares e de pureza ritual","Foram substitu\xEDdas por um novo conjunto de leis cerimoniais pr\xF3prias da Igreja crist\xE3","Continuam obrigando os crist\xE3os de origem judaica, embora n\xE3o os gentios convertidos","Nunca foram formalmente abolidas, apenas reinterpretadas espiritualmente pela Igreja","Est\xE3o todas abrogadas sob o Novo Testamento, tendo prefigurado Cristo e seus benef\xEDcios"],respostaCorreta:"Est\xE3o todas abrogadas sob o Novo Testamento, tendo prefigurado Cristo e seus benef\xEDcios",explicacao:"Se\xE7\xE3o III: essas leis cerimoniais 'est\xE3o todas abrogadas sob o Novo Testamento'."},{id:87,capitulo:"XVI - Das Boas Obras",pergunta:"Segundo a Se\xE7\xE3o VII, as obras moralmente boas realizadas por pessoas n\xE3o regeneradas s\xE3o descritas pela Confiss\xE3o como:",alternativas:["Neutras diante de Deus, nem boas nem m\xE1s, j\xE1 que dependem apenas da inten\xE7\xE3o subjetiva de quem as pratica, ainda que alguns leitores tentem harmoniz\xE1-la com o restante do cap\xEDtulo","Merit\xF3rias o suficiente para preparar o n\xE3o regenerado a receber a gra\xE7a salvadora, apesar de soar plaus\xEDvel a uma leitura apressada do cap\xEDtulo","Pecaminosas diante de Deus, por n\xE3o procederem de um cora\xE7\xE3o purificado pela f\xE9 nem visarem \xE0 gl\xF3ria de Deus, embora negligenci\xE1-las seja ainda mais ofensivo","Irrelevantes para a avalia\xE7\xE3o moral, pois s\xF3 contam as obras realizadas ap\xF3s a convers\xE3o, contrariando o sentido direto do texto citado nessa se\xE7\xE3o","Plenamente aceit\xE1veis diante de Deus, desde que \xFAteis \xE0 sociedade e sinceramente motivadas, tal como sustentado por correntes teol\xF3gicas distintas da reformada"],respostaCorreta:"Pecaminosas diante de Deus, por n\xE3o procederem de um cora\xE7\xE3o purificado pela f\xE9 nem visarem \xE0 gl\xF3ria de Deus, embora negligenci\xE1-las seja ainda mais ofensivo",explicacao:"Se\xE7\xE3o VII: tais obras 'n\xE3o s\xE3o feitas devidamente... nem para um fim justo... s\xE3o pecaminosas e n\xE3o podem agradar a Deus', mas negligenci\xE1-las \xE9 ainda mais pecaminoso."},{id:88,capitulo:"XXIX - Da Ceia do Senhor",pergunta:"A Se\xE7\xE3o VI, que rejeita a doutrina da transubstancia\xE7\xE3o por ser contr\xE1ria \xE0s Escrituras, ao senso comum e \xE0 raz\xE3o, cita qual destas refer\xEAncias?",alternativas:["I Tim. 1:3-4 (citada na Se\xE7\xE3o IV, sobre a rejei\xE7\xE3o da adora\xE7\xE3o dos elementos)","Heb. 9:22, 25-26 (citada na Se\xE7\xE3o II, sobre a rejei\xE7\xE3o do sacrif\xEDcio da missa)","Luc. 24:6, 39","Mar. 14:22-24 (citada na Se\xE7\xE3o III, sobre o minist\xE9rio da palavra de institui\xE7\xE3o)","I Cor. 11:23-26 (citada na Se\xE7\xE3o I, sobre a institui\xE7\xE3o da Ceia do Senhor)"],respostaCorreta:"Luc. 24:6, 39",explicacao:"A Se\xE7\xE3o VI cita At. 3:21, I Cor. 11:24-26 e Luc. 24:6, 39 \u2014 este \xFAltimo associado \xE0 ressurrei\xE7\xE3o corporal de Cristo, argumento contra a transubstancia\xE7\xE3o; as demais pertencem a outras se\xE7\xF5es."},{id:89,capitulo:"XX - Da Liberdade Crist\xE3 e da Liberdade de Consci\xEAncia",pergunta:"Segundo a Se\xE7\xE3o II, exigir f\xE9 impl\xEDcita e obedi\xEAncia cega a doutrinas ou mandamentos humanos contr\xE1rios ou alheios \xE0 palavra de Deus \xE9 descrito pela Confiss\xE3o como:",alternativas:["Um exerc\xEDcio toler\xE1vel de disciplina, desde que confirmado por consenso da congrega\xE7\xE3o local","Uma express\xE3o v\xE1lida da submiss\xE3o crist\xE3 \xE0 autoridade humana, mesmo sem base b\xEDblica direta","Uma pr\xE1tica neutra, aceit\xE1vel enquanto n\xE3o contradiga diretamente um mandamento expl\xEDcito da Escritura","Um exerc\xEDcio leg\xEDtimo de autoridade eclesi\xE1stica, desde que exercido por oficiais devidamente ordenados","Uma trai\xE7\xE3o \xE0 verdadeira liberdade de consci\xEAncia, e destrui\xE7\xE3o dessa liberdade e da pr\xF3pria raz\xE3o"],respostaCorreta:"Uma trai\xE7\xE3o \xE0 verdadeira liberdade de consci\xEAncia, e destrui\xE7\xE3o dessa liberdade e da pr\xF3pria raz\xE3o",explicacao:"Se\xE7\xE3o II: exigir f\xE9 impl\xEDcita e obedi\xEAncia cega e absoluta '\xE9 destruir a liberdade de consci\xEAncia e a mesma raz\xE3o'."},{id:90,capitulo:"XXXV - Do Amor de Deus e das Miss\xF5es",pergunta:"Segundo a Se\xE7\xE3o III, quem \xE9 apontado como o \xFAnico respons\xE1vel por sua pr\xF3pria perdi\xE7\xE3o, entre os que ouvem o Evangelho?",alternativas:["Deus, por n\xE3o ter decretado a salva\xE7\xE3o de todos os que ouvem o Evangelho igualmente","A Igreja, por n\xE3o ter pregado com suficiente clareza a mensagem em todos os casos","Os pais ou respons\xE1veis, por n\xE3o terem instru\xEDdo adequadamente os que rejeitam a f\xE9","Os que continuam impenitentes e incr\xE9dulos diante da oferta do Evangelho j\xE1 ouvida","Ningu\xE9m em particular, j\xE1 que a perdi\xE7\xE3o \xE9 atribu\xEDda inteiramente a causas impessoais"],respostaCorreta:"Os que continuam impenitentes e incr\xE9dulos diante da oferta do Evangelho j\xE1 ouvida",explicacao:"Se\xE7\xE3o III: 'os que continuam impenitentes e incr\xE9dulos agravam a sua falta e s\xE3o os \xFAnicos culpados pela sua perdi\xE7\xE3o'."},{id:91,capitulo:"XXI - Do Culto Religioso e do Domingo",pergunta:"Segundo a Se\xE7\xE3o VII, desde a ressurrei\xE7\xE3o de Cristo at\xE9 o fim do mundo, o s\xE1bado crist\xE3o deve ser observado:",alternativas:["No primeiro dia da semana, chamado Domingo, ou dia do Senhor","Em qualquer dia da semana, \xE0 escolha de cada crente, conforme sua conveni\xEAncia","No s\xE9timo dia da semana, tal como antes da ressurrei\xE7\xE3o, sem altera\xE7\xE3o alguma","N\xE3o h\xE1 mais um dia especialmente separado sob a nova alian\xE7a do Evangelho","Apenas em ocasi\xF5es especiais determinadas pelo calend\xE1rio lit\xFArgico de cada igreja"],respostaCorreta:"No primeiro dia da semana, chamado Domingo, ou dia do Senhor",explicacao:"Se\xE7\xE3o VII: o dia foi mudado do \xFAltimo para o primeiro dia da semana, chamado Domingo, e h\xE1 de continuar at\xE9 o fim do mundo como o s\xE1bado crist\xE3o."},{id:92,capitulo:"XXI - Do Culto Religioso e do Domingo",pergunta:"Segundo a Se\xE7\xE3o I, o modo aceit\xE1vel de adorar a Deus \xE9 determinado por qual princ\xEDpio \u2014 em contraste com uma pr\xE1tica lit\xFArgica que permite tudo o que n\xE3o \xE9 expressamente proibido?",alternativas:["Deve seguir a tradi\xE7\xE3o consolidada da Igreja, ainda quando n\xE3o explicitamente prescrita na Escritura","Pode incluir qualquer pr\xE1tica que n\xE3o seja expressamente proibida nas Escrituras, desde que edificante","Deve equilibrar a Escritura com a raz\xE3o natural, complementando uma pela outra quando necess\xE1rio","Deve ser institu\xEDdo pelo pr\xF3prio Deus e limitado \xE0 sua vontade revelada, n\xE3o podendo seguir inven\xE7\xF5es humanas","Fica a crit\xE9rio de cada congrega\xE7\xE3o local, conforme sua cultura e contexto hist\xF3rico espec\xEDfico"],respostaCorreta:"Deve ser institu\xEDdo pelo pr\xF3prio Deus e limitado \xE0 sua vontade revelada, n\xE3o podendo seguir inven\xE7\xF5es humanas",explicacao:"Se\xE7\xE3o I segue o chamado 'princ\xEDpio regulador do culto': s\xF3 \xE9 aceit\xE1vel o que Deus mesmo instituiu, n\xE3o 'as imagina\xE7\xF5es e inven\xE7\xF5es dos homens' \u2014 em contraste com o 'princ\xEDpio normativo' de outras tradi\xE7\xF5es protestantes."}];export{a as QUESTIONARIO_WESTMINSTER};
